window.C3KO_DATA = {"version":1,"levels":[{"id":"A1","name":["Beginner","Pemula"],"goal":["Introduce yourself, talk about daily life, ask and answer simple questions.","Memperkenalkan diri, membicarakan kehidupan sehari-hari, bertanya dan menjawab hal sederhana."],"topics":[{"id":"a1-sounds","title":["Sounds, silent letters, accents & liaison","Bunyi, huruf diam, aksen & liaison"],"what":["French spelling has many silent letters, especially final consonants and final -e. Accents change the sound of e (é, è, ê) or just tell words apart (à / a, où / ou). Before a vowel or silent h, some final consonants are pronounced (liaison) and small words like le, je, ne lose their vowel (élision).","Ejaan bahasa Prancis punya banyak huruf diam, terutama konsonan akhir dan -e akhir. Aksen mengubah bunyi e (é, è, ê) atau hanya membedakan kata (à / a, où / ou). Sebelum vokal atau h diam, beberapa konsonan akhir dibunyikan (liaison) dan kata kecil seperti le, je, ne kehilangan vokalnya (elisi)."],"pattern":[{"title":["Key spellings","Ejaan penting"],"head":[["Spelling","Ejaan"],["Sound","Bunyi"],["Example","Contoh"]],"rows":[["{é}",["closed e, like 'ay' without the y","e tertutup, seperti é dalam 'sate'"],"café, été"],["{è} / {ê}",["open e, as in 'bed'","e terbuka, seperti e dalam 'bebek'"],"mère, fête"],["{ou}",["oo","u"],"vous, rouge"],["{u}",["ee with rounded lips","i dengan bibir bulat"],"tu, rue"],["{oi}",["wa","wa"],"moi, trois"],["{au} / {eau}",["o","o"],"chaud, beau"],["{an/en}, {on}, {in/ain}",["nasal vowels","vokal sengau"],"enfant, bon, vin, pain"],["{ç}",["s","s"],"français, garçon"],["{gn}",["ny","ny"],"montagne"],["{h}",["always silent","selalu diam"],"hôtel, homme"]]},{"title":["Élision and liaison","Elisi dan liaison"],"head":[["Rule","Aturan"],["Example","Contoh"]],"rows":[[["le, la, je, me, te, se, ne, de, que → l', j', m'… before a vowel or silent h","le, la, je, me, te, se, ne, de, que → l', j', m'… sebelum vokal atau h diam"],"{l'}ami, {j'}aime, {l'}hôtel, {n'}est"],[["final consonant linked to the next vowel","konsonan akhir disambung ke vokal berikutnya"],"les_amis (lé-z-ami), vous_avez (vou-z-avé)"],[["final consonant usually silent","konsonan akhir biasanya tidak dibaca"],"petit, grand, vous, Paris"]]}],"examples":[["Bonjour, je m'appelle Léa.",["Hello, my name is Léa.","Halo, nama saya Léa."]],["Comment ça va ? — Ça va bien, merci.",["How are you? — I'm fine, thanks.","Apa kabar? — Baik, terima kasih."]],["J'habite à Lyon.",["I live in Lyon.","Saya tinggal di Lyon."]]],"tip":["Never write 'je aime' or 'le hôtel': élision is compulsory in writing too. In French typography, ? ! : ; take a space before them: Ça va ?","Jangan menulis 'je aime' atau 'le hôtel': elisi wajib juga dalam tulisan. Dalam tipografi Prancis, ? ! : ; diberi spasi sebelumnya: Ça va ?"]},{"id":"a1-pronouns","title":["Subject pronouns & tu vs vous","Kata ganti subjek & tu vs vous"],"what":["French always needs a subject pronoun, because many verb forms sound the same. Tu is informal 'you'; vous is both polite 'you' and plural 'you'. On means 'we' in everyday speech (and 'people / one') but takes the il/elle verb form.","Bahasa Prancis selalu memerlukan kata ganti subjek, karena banyak bentuk kata kerja berbunyi sama. Tu adalah 'kamu' informal; vous berarti 'Anda' (sopan) sekaligus 'kalian'. On berarti 'kita' dalam percakapan sehari-hari (dan 'orang'), tetapi memakai bentuk kata kerja il/elle."],"pattern":[{"head":[["Person","Persona"],["Singular","Tunggal"],["Plural","Jamak"]],"rows":[["1","{je} (j')","{nous}"],["2",["{tu} (informal)","{tu} (informal)"],["{vous} (polite or plural)","{vous} (sopan atau jamak)"]],["3","{il} / {elle} / {on}","{ils} / {elles}"]],"note":["ils is used for any group with at least one male; elles only for all-female groups.","ils dipakai untuk kelompok yang ada laki-lakinya; elles hanya untuk kelompok yang semuanya perempuan."]},{"title":["Stressed pronouns (alone, after prepositions, for emphasis)","Kata ganti penekanan (berdiri sendiri, setelah kata depan, untuk penekanan)"],"head":["je","tu","il / elle","nous","vous","ils / elles"],"rows":[["{moi}","{toi}","{lui} / {elle}","{nous}","{vous}","{eux} / {elles}"]]}],"examples":[["Tu es d'où ? — Moi, je suis de Nantes.",["Where are you from? — Me, I'm from Nantes.","Kamu dari mana? — Saya dari Nantes."]],["Vous parlez anglais, madame ?",["Do you speak English, madam?","Apakah Anda bisa berbahasa Inggris, Bu?"]],["On va au cinéma ce soir.",["We're going to the cinema tonight.","Kita pergi ke bioskop malam ini."]]],"tip":["Use vous with strangers, shop staff and older people until they suggest tu ('On se tutoie ?'). With on the verb is singular: on est, on va.","Pakai vous dengan orang asing, petugas toko dan orang yang lebih tua sampai mereka menawarkan tu ('On se tutoie ?'). Dengan on, kata kerjanya tunggal: on est, on va."]},{"id":"a1-articles","title":["Nouns: gender, articles & plurals","Kata benda: gender, artikel & jamak"],"what":["Every noun is masculine or feminine. Le/un go with masculine nouns, la/une with feminine ones; les/des are the plural for both. Before a vowel or silent h, le and la become l'. Most plurals add a silent -s, so the article is often the only audible sign of the plural.","Setiap kata benda bergender maskulin atau feminin. Le/un untuk kata benda maskulin, la/une untuk feminin; les/des adalah bentuk jamak keduanya. Sebelum vokal atau h diam, le dan la menjadi l'. Kebanyakan bentuk jamak ditambah -s yang tidak dibaca, jadi artikel sering menjadi satu-satunya tanda jamak yang terdengar."],"pattern":[{"title":["Articles","Artikel"],"head":["",["Definite (the)","Takrif (the)"],["Indefinite (a / some)","Taktakrif (a / beberapa)"]],"rows":[[["masculine","maskulin"],"{le} livre · {l'}ami","{un} livre"],[["feminine","feminin"],"{la} maison · {l'}école","{une} maison"],[["plural","jamak"],"{les} livres, {les} maisons","{des} livres, {des} maisons"]]},{"title":["Gender clues and plurals","Petunjuk gender dan jamak"],"head":[["Ending","Akhiran"],["Usually","Biasanya"],["Examples","Contoh"]],"rows":[["-age, -ment, -eau, -isme",["masculine","maskulin"],"le fromage, le moment, le bureau"],["-tion, -sion, -té, -ure, -ette",["feminine","feminin"],"la nation, la liberté, la voiture"],[["plural: most nouns","jamak: kebanyakan kata benda"],"+ {s}","livre{s}, maison{s}"],[["-eau, -eu","-eau, -eu"],"+ {x}","gâteau{x}, jeu{x}"],[["-al","-al"],"→ {-aux}","journal → journ{aux}"],[["-s, -x, -z","-s, -x, -z"],["no change","tidak berubah"],"le bus → les bus, le prix → les prix"]],"note":["Exceptions to learn early: la plage, l'image (f.), le musée, le lycée (m.). Irregular: un œil → des yeux.","Pengecualian yang perlu dihafal sejak awal: la plage, l'image (f.), le musée, le lycée (m.). Tidak beraturan: un œil → des yeux."]}],"examples":[["J'ai un frère et une sœur.",["I have a brother and a sister.","Saya punya satu saudara laki-laki dan satu saudara perempuan."]],["Les enfants sont à l'école.",["The children are at school.","Anak-anak ada di sekolah."]],["Il y a des gâteaux.",["There are (some) cakes.","Ada kue-kue."]]],"tip":["Unlike English, the plural 'some' needs des: 'J'ai des amis à Paris' (I have friends in Paris). A noun almost never stands without an article.","Berbeda dengan bahasa Inggris, bentuk jamak 'beberapa' memerlukan des: 'J'ai des amis à Paris'. Kata benda hampir tidak pernah berdiri tanpa artikel."]},{"id":"a1-adjectives","title":["Adjectives: agreement & position","Kata sifat: kesesuaian & posisi"],"what":["Adjectives agree with the noun: add -e for feminine and -s for plural. Adjectives already ending in -e don't add another. Most adjectives come after the noun; a small group of common ones (beauty, age, goodness, size — 'BAGS') come before it.","Kata sifat menyesuaikan kata bendanya: tambah -e untuk feminin dan -s untuk jamak. Kata sifat yang sudah berakhiran -e tidak ditambah lagi. Kebanyakan kata sifat diletakkan setelah kata benda; sekelompok kecil kata sifat umum (keindahan, usia, kebaikan, ukuran — 'BAGS') diletakkan sebelumnya."],"pattern":[{"head":[["Type","Jenis"],["masc. sg.","mask. tg."],["fem. sg.","fem. tg."],["masc. pl.","mask. jm."],["fem. pl.","fem. jm."]],"rows":[[["regular","beraturan"],"petit","petit{e}","petit{s}","petit{es}"],[["ends in -e","berakhiran -e"],"rouge","rouge","rouge{s}","rouge{s}"],["-eux","heureux","heur{euse}","heureux","heur{euses}"],["-if","sportif","sport{ive}","sportif{s}","sport{ives}"],["-en / -on","italien","italien{ne}","italien{s}","italien{nes}"],[["irregular","tidak beraturan"],"beau (bel)","{belle}","{beaux}","{belles}"],[["irregular","tidak beraturan"],"nouveau (nouvel)","{nouvelle}","{nouveaux}","{nouvelles}"],[["irregular","tidak beraturan"],"vieux (vieil)","{vieille}","vieux","{vieilles}"]],"note":["Before the noun: beau, joli, jeune, vieux, nouveau, bon, mauvais, grand, petit, gros. beau/nouveau/vieux become bel/nouvel/vieil before a masculine vowel: un bel homme.","Sebelum kata benda: beau, joli, jeune, vieux, nouveau, bon, mauvais, grand, petit, gros. beau/nouveau/vieux menjadi bel/nouvel/vieil sebelum kata maskulin yang diawali vokal: un bel homme."]}],"examples":[["une voiture rouge",["a red car","mobil merah"]],["un petit appartement",["a small flat","apartemen kecil"]],["Mes amies sont très sportives.",["My (female) friends are very sporty.","Teman-teman perempuan saya sangat suka olahraga."]]],"tip":["Colours and nationalities always go after the noun, and nationality adjectives are lower case: un film français.","Warna dan kebangsaan selalu diletakkan setelah kata benda, dan kata sifat kebangsaan ditulis huruf kecil: un film français."]},{"id":"a1-etre","title":["Être (to be)","Être (adalah, berada)"],"what":["Être is irregular and very frequent: identity, nationality, job, description, location. With a job after être there is normally no article: Je suis médecin.","Être tidak beraturan dan sangat sering dipakai: identitas, kebangsaan, pekerjaan, deskripsi, lokasi. Untuk pekerjaan setelah être biasanya tanpa artikel: Je suis médecin."],"pattern":[{"head":[["Person","Persona"],"être",["Example","Contoh"]],"rows":[["je","{suis}","Je {suis} étudiante."],["tu","{es}","Tu {es} fatigué ?"],["il / elle / on","{est}","Elle {est} à la maison."],["nous","{sommes}","Nous {sommes} canadiens."],["vous","{êtes}","Vous {êtes} en retard."],["ils / elles","{sont}","Ils {sont} gentils."]],"note":["C'est + noun with article / name: C'est un ami. C'est Léa. Il/Elle est + adjective or job: Il est grand. Il est professeur.","C'est + kata benda dengan artikel / nama: C'est un ami. C'est Léa. Il/Elle est + kata sifat atau pekerjaan: Il est grand. Il est professeur."]}],"examples":[["Je suis français.",["I'm French.","Saya orang Prancis."]],["C'est mon frère. Il est infirmier.",["This is my brother. He's a nurse.","Ini saudara laki-laki saya. Dia perawat."]],["Où est la gare ?",["Where is the station?","Di mana stasiunnya?"]]],"tip":["Say 'Il est médecin' or 'C'est un médecin', but not 'Il est un médecin'.","Katakan 'Il est médecin' atau 'C'est un médecin', tetapi jangan 'Il est un médecin'."]},{"id":"a1-avoir","title":["Avoir (to have) and its expressions","Avoir (punya) dan ungkapannya"],"what":["Avoir means 'to have'. French uses avoir where English uses 'be' for age and physical feelings: j'ai 20 ans, j'ai faim. Avoir is also the main helper verb of the passé composé (A2).","Avoir berarti 'punya'. Bahasa Prancis memakai avoir untuk umur dan perasaan fisik: j'ai 20 ans (umur saya 20 tahun), j'ai faim (saya lapar). Avoir juga kata kerja bantu utama passé composé (A2)."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"avoir"],"rows":[["je","{ai} (j'ai)"],["tu","{as}"],["il / elle / on","{a}"],["nous","{avons}"],["vous","{avez}"],["ils / elles","{ont}"]]},{"title":["Expressions","Ungkapan"],"head":[["French","Prancis"],["Meaning","Arti"]],"rows":[["avoir … {ans}",["be … years old","berumur … tahun"]],["avoir {faim} / {soif}",["be hungry / thirsty","lapar / haus"]],["avoir {chaud} / {froid}",["be hot / cold (person)","kepanasan / kedinginan"]],["avoir {sommeil} / {peur}",["be sleepy / afraid","mengantuk / takut"]],["avoir {raison} / {tort}",["be right / wrong","benar / salah"]],["avoir {besoin de}",["need","membutuhkan"]],["avoir {mal à} + body part",["have a pain in","sakit (bagian tubuh)"]]]}],"examples":[["J'ai vingt-cinq ans.",["I'm twenty-five.","Umur saya dua puluh lima tahun."]],["Tu as faim ?",["Are you hungry?","Kamu lapar?"]],["J'ai besoin d'un taxi.",["I need a taxi.","Saya butuh taksi."]]],"tip":["Don't confuse ils ont (they have, liaison with z: il-z-ont) and ils sont (they are).","Jangan tertukar ils ont (mereka punya, dibaca il-z-ont) dan ils sont (mereka adalah)."]},{"id":"a1-present-er","title":["Present tense: -er verbs","Kala kini: kata kerja -er"],"what":["About 90% of French verbs end in -er and are regular. Remove -er and add the endings. Four forms (je, tu, il, ils) sound the same; only nous (-ons) and vous (-ez) sound different. The present covers 'I work' and 'I'm working'.","Sekitar 90% kata kerja Prancis berakhiran -er dan beraturan. Buang -er lalu tambahkan akhirannya. Empat bentuk (je, tu, il, ils) berbunyi sama; hanya nous (-ons) dan vous (-ez) yang terdengar berbeda. Kala kini mencakup 'saya bekerja' dan 'saya sedang bekerja'."],"pattern":[{"head":[["Person","Persona"],"parler","aimer",["Ending","Akhiran"]],"rows":[["je / j'","parl{e}","j'aim{e}","-e"],["tu","parl{es}","aim{es}","-es"],["il / elle / on","parl{e}","aim{e}","-e"],["nous","parl{ons}","aim{ons}","-ons"],["vous","parl{ez}","aim{ez}","-ez"],["ils / elles","parl{ent}","aim{ent}",["-ent (silent)","-ent (tidak dibaca)"]]],"note":["Spelling: manger → nous mangeons, commencer → nous commençons (to keep the soft g/c). acheter → j'achète, appeler → j'appelle, préférer → je préfère (not for nous/vous).","Ejaan: manger → nous mangeons, commencer → nous commençons (agar g/c tetap lunak). acheter → j'achète, appeler → j'appelle, préférer → je préfère (tidak untuk nous/vous)."]}],"examples":[["Je parle français et un peu d'espagnol.",["I speak French and a little Spanish.","Saya bisa bahasa Prancis dan sedikit bahasa Spanyol."]],["Vous habitez où ?",["Where do you live?","Anda tinggal di mana?"]],["Nous mangeons à midi.",["We eat at noon.","Kami makan pukul dua belas siang."]]],"tip":["The -ent of ils parlent is never pronounced: 'il parle' and 'ils parlent' sound identical.","-ent pada ils parlent tidak pernah dibaca: 'il parle' dan 'ils parlent' berbunyi sama."]},{"id":"a1-present-irregular","title":["Present tense: -ir verbs and common irregular verbs","Kala kini: kata kerja -ir dan kata kerja tidak beraturan umum"],"what":["Regular -ir verbs (2nd group, like finir) add -iss- in the plural. Many very common verbs are irregular and must be learned by heart: aller, faire, prendre, venir, pouvoir, vouloir, devoir, savoir.","Kata kerja -ir beraturan (kelompok 2, seperti finir) mendapat -iss- pada bentuk jamak. Banyak kata kerja yang sangat umum tidak beraturan dan harus dihafal: aller, faire, prendre, venir, pouvoir, vouloir, devoir, savoir."],"pattern":[{"head":[["Person","Persona"],"finir","aller","faire","prendre","venir"],"rows":[["je","fin{is}","{vais}","{fais}","{prends}","{viens}"],["tu","fin{is}","{vas}","{fais}","{prends}","{viens}"],["il / elle / on","fin{it}","{va}","{fait}","{prend}","{vient}"],["nous","fin{issons}","{allons}","{faisons}","{prenons}","{venons}"],["vous","fin{issez}","{allez}","{faites}","{prenez}","{venez}"],["ils / elles","fin{issent}","{vont}","{font}","{prennent}","{viennent}"]]},{"title":["Modal verbs","Kata kerja modal"],"head":[["Person","Persona"],["pouvoir (can)","pouvoir (bisa)"],["vouloir (want)","vouloir (mau)"],["devoir (must)","devoir (harus)"]],"rows":[["je","{peux}","{veux}","{dois}"],["tu","{peux}","{veux}","{dois}"],["il / elle / on","{peut}","{veut}","{doit}"],["nous","{pouvons}","{voulons}","{devons}"],["vous","{pouvez}","{voulez}","{devez}"],["ils / elles","{peuvent}","{veulent}","{doivent}"]],"note":["Modals are followed by an infinitive: Je peux venir. 'Je voudrais' (I would like) is the polite form of vouloir.","Kata kerja modal diikuti infinitif: Je peux venir. 'Je voudrais' (saya ingin) adalah bentuk sopan dari vouloir."]}],"examples":[["Je vais au travail en métro.",["I go to work by metro.","Saya pergi ke kantor naik metro."]],["Qu'est-ce que tu fais ce week-end ?",["What are you doing this weekend?","Apa yang kamu lakukan akhir pekan ini?"]],["Je voudrais un café, s'il vous plaît.",["I'd like a coffee, please.","Saya mau kopi, tolong."]]],"tip":["Vous faites and vous dites end in -tes, not -ez. 'Vous faisez' is a classic mistake.","Vous faites dan vous dites berakhiran -tes, bukan -ez. 'Vous faisez' adalah kesalahan klasik."]},{"id":"a1-negation","title":["Negation: ne … pas","Negasi: ne … pas"],"what":["French negation has two parts around the conjugated verb: ne before it, pas after it. Ne becomes n' before a vowel. After a negation, un, une, des and du, de la become de (d'). In everyday speech ne is often dropped, but write it.","Negasi bahasa Prancis punya dua bagian yang mengapit kata kerja terkonjugasi: ne sebelumnya, pas sesudahnya. Ne menjadi n' sebelum vokal. Setelah negasi, un, une, des dan du, de la menjadi de (d'). Dalam percakapan ne sering dihilangkan, tetapi tetap ditulis."],"pattern":[{"head":[["Pattern","Pola"],["Positive","Positif"],["Negative","Negatif"]],"rows":[[["simple verb","kata kerja sederhana"],"Je parle allemand.","Je {ne} parle {pas} allemand."],[["before a vowel","sebelum vokal"],"J'aime le café.","Je {n'}aime {pas} le café."],[["un / une / des → de","un / une / des → de"],"J'ai une voiture.","Je n'ai pas {de} voiture."],[["du / de la → de","du / de la → de"],"Je bois du lait.","Je ne bois pas {de} lait."],[["verb + infinitive","kata kerja + infinitif"],"Je veux partir.","Je {ne} veux {pas} partir."]],"note":["Other negatives: ne … jamais (never), ne … plus (no longer), ne … rien (nothing), ne … personne (nobody) — see A2.","Negasi lain: ne … jamais (tidak pernah), ne … plus (tidak lagi), ne … rien (tidak apa-apa), ne … personne (tidak seorang pun) — lihat A2."]}],"examples":[["Je ne comprends pas.",["I don't understand.","Saya tidak mengerti."]],["Il n'a pas d'enfants.",["He doesn't have any children.","Dia tidak punya anak."]],["Ce n'est pas grave.",["It doesn't matter.","Tidak apa-apa."]]],"tip":["The article stays after être: 'Ce n'est pas un problème' (not 'pas de problème' here, because c'est is être).","Artikel tetap dipakai setelah être: 'Ce n'est pas un problème' (bukan 'pas de' di sini, karena c'est memakai être)."]},{"id":"a1-questions","title":["Asking questions","Membuat pertanyaan"],"what":["There are three ways to ask a yes/no question: rising intonation (most common in speech), est-ce que at the start (neutral), or inversion of subject and verb (formal). Question words can go at the start with est-ce que or inversion, or at the end in casual speech.","Ada tiga cara membuat pertanyaan ya/tidak: intonasi naik (paling umum dalam percakapan), est-ce que di awal (netral), atau inversi subjek dan kata kerja (formal). Kata tanya bisa di awal dengan est-ce que atau inversi, atau di akhir dalam percakapan santai."],"pattern":[{"title":["Three registers","Tiga ragam"],"head":[["Style","Gaya"],["Yes/no","Ya/tidak"],["With a question word","Dengan kata tanya"]],"rows":[[["intonation (casual)","intonasi (santai)"],"Tu viens ?","Tu vas {où} ?"],[["est-ce que (neutral)","est-ce que (netral)"],"{Est-ce que} tu viens ?","{Où est-ce que} tu vas ?"],[["inversion (formal)","inversi (formal)"],"{Viens-tu} ?","{Où vas-tu} ?"]],"note":["Inversion with il/elle after a vowel adds -t-: Parle-t-il anglais ? A-t-elle un chien ?","Inversi dengan il/elle setelah vokal ditambah -t-: Parle-t-il anglais ? A-t-elle un chien ?"]},{"title":["Question words","Kata tanya"],"head":[["French","Prancis"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{qui}",["who","siapa"],"Qui est-ce ?"],["{que / qu'est-ce que / quoi}",["what","apa"],"Qu'est-ce que tu fais ? Tu fais quoi ?"],["{où}",["where","di mana / ke mana"],"Où habites-tu ?"],["{quand}",["when","kapan"],"Quand est-ce que tu pars ?"],["{comment}",["how","bagaimana"],"Comment tu t'appelles ?"],["{pourquoi}",["why","mengapa"],"Pourquoi ? — Parce que…"],["{combien (de)}",["how much / many","berapa"],"Combien ça coûte ?"],["{quel / quelle / quels / quelles}",["which, what (+ noun)","yang mana, apa (+ kata benda)"],"Quelle heure est-il ?"]]}],"examples":[["Est-ce que vous avez une chambre ?",["Do you have a room?","Apakah Anda punya kamar?"]],["Tu t'appelles comment ?",["What's your name?","Siapa namamu?"]],["Quel âge as-tu ?",["How old are you?","Berapa umurmu?"]]],"tip":["Quel agrees with the noun: quel livre, quelle ville, quels films, quelles questions — all four sound the same.","Quel menyesuaikan kata bendanya: quel livre, quelle ville, quels films, quelles questions — keempatnya berbunyi sama."]},{"id":"a1-il-y-a","title":["Il y a (there is / there are)","Il y a (ada)"],"what":["Il y a says that something exists somewhere, for singular and plural alike. It is usually followed by un, une, des, a number or a quantity. The negative is il n'y a pas de.","Il y a menyatakan bahwa sesuatu ada di suatu tempat, untuk tunggal maupun jamak. Biasanya diikuti un, une, des, angka atau jumlah. Bentuk negatifnya il n'y a pas de."],"pattern":[{"head":[["Use","Pemakaian"],["Form","Bentuk"],["Example","Contoh"]],"rows":[[["exists","ada"],"{il y a} + un / une / des","{Il y a} une pharmacie ici."],[["negative","negatif"],"{il n'y a pas de}","{Il n'y a pas de} pain."],[["question","pertanyaan"],"{Est-ce qu'il y a} … ? / {Y a-t-il} … ?","{Est-ce qu'il y a} un bus ?"],[["specific thing: where","benda tertentu: letaknya"],"le / la / les … + {être}","La pharmacie {est} à côté."],[["ago (with time)","yang lalu (dengan waktu)"],"{il y a} + time","Je suis arrivé {il y a} deux jours."]]}],"examples":[["Dans ma rue, il y a deux boulangeries.",["On my street there are two bakeries.","Di jalan saya ada dua toko roti."]],["Il n'y a pas de problème.",["There's no problem.","Tidak ada masalah."]],["Qu'est-ce qu'il y a ?",["What's the matter?","Ada apa?"]]],"tip":["Il y a never changes to 'ils y ont' for plurals: il y a trois chambres.","Il y a tidak pernah berubah menjadi 'ils y ont' untuk jamak: il y a trois chambres."]},{"id":"a1-possessives","title":["Possessive adjectives","Kata sifat kepemilikan"],"what":["Possessives agree with the thing owned, not with the owner: sa mère can be 'his mother' or 'her mother'. Before a feminine noun starting with a vowel, use mon/ton/son for sound: mon amie, son école.","Kata kepemilikan menyesuaikan benda yang dimiliki, bukan pemiliknya: sa mère bisa berarti 'ibunya (laki-laki)' atau 'ibunya (perempuan)'. Sebelum kata benda feminin yang diawali vokal, pakai mon/ton/son demi bunyi: mon amie, son école."],"pattern":[{"head":[["Owner","Pemilik"],["masc. sg.","mask. tg."],["fem. sg.","fem. tg."],["plural","jamak"]],"rows":[["je","{mon} frère","{ma} sœur","{mes} parents"],["tu","{ton} frère","{ta} sœur","{tes} parents"],["il / elle","{son} frère","{sa} sœur","{ses} parents"],["nous","{notre} frère","{notre} sœur","{nos} parents"],["vous","{votre} frère","{votre} sœur","{vos} parents"],["ils / elles","{leur} frère","{leur} sœur","{leurs} parents"]]}],"examples":[["Ma sœur habite à Bordeaux.",["My sister lives in Bordeaux.","Saudara perempuan saya tinggal di Bordeaux."]],["Thomas parle avec sa mère.",["Thomas is talking to his mother.","Thomas berbicara dengan ibunya."]],["C'est mon amie Julie.",["This is my friend Julie.","Ini teman saya, Julie."]]],"tip":["Leur (their) has no -s with one thing (leur maison) and -s with several (leurs enfants).","Leur (milik mereka) tanpa -s untuk satu benda (leur maison) dan dengan -s untuk beberapa (leurs enfants)."]},{"id":"a1-demonstratives","title":["Demonstratives: ce, cet, cette, ces","Kata tunjuk: ce, cet, cette, ces"],"what":["Ce/cet/cette/ces mean both 'this' and 'that'. Cet is the masculine form before a vowel or silent h. To contrast near and far, add -ci (here) or -là (there) to the noun.","Ce/cet/cette/ces berarti 'ini' sekaligus 'itu'. Cet adalah bentuk maskulin sebelum vokal atau h diam. Untuk membedakan dekat dan jauh, tambahkan -ci (sini) atau -là (sana) pada kata bendanya."],"pattern":[{"head":["",["Form","Bentuk"],["Example","Contoh"]],"rows":[[["masculine","maskulin"],"{ce}","{ce} livre"],[["masc. before vowel / h","mask. sebelum vokal / h"],"{cet}","{cet} homme, {cet} ami"],[["feminine","feminin"],"{cette}","{cette} maison"],[["plural","jamak"],"{ces}","{ces} enfants"],[["contrast","kontras"],"-{ci} / -{là}","ce pull-{ci} ou ce pull-{là} ?"]]}],"examples":[["Cette robe est jolie.",["This/That dress is pretty.","Gaun ini/itu cantik."]],["Je travaille cet après-midi.",["I'm working this afternoon.","Saya bekerja sore ini."]],["Ces chaussures sont trop chères.",["These/Those shoes are too expensive.","Sepatu ini/itu terlalu mahal."]]],"tip":["Ce + time word means 'this' period: ce matin, ce soir, cette semaine, cet été.","Ce + kata waktu berarti periode 'ini': ce matin, ce soir, cette semaine, cet été."]},{"id":"a1-partitive","title":["Partitive articles: du, de la, des","Artikel partitif: du, de la, des"],"what":["For an unspecified amount of something you can't count (bread, water, patience), French uses du (masculine), de la (feminine), de l' (before a vowel). Talking about likes uses le/la/les (in general); eating and buying uses du/de la (some).","Untuk jumlah tak tentu dari sesuatu yang tidak bisa dihitung (roti, air, kesabaran), bahasa Prancis memakai du (maskulin), de la (feminin), de l' (sebelum vokal). Membicarakan kesukaan memakai le/la/les (umum); makan dan membeli memakai du/de la (sebagian)."],"pattern":[{"head":[["Use","Pemakaian"],["Article","Artikel"],["Example","Contoh"]],"rows":[[["some (masculine)","sebagian (maskulin)"],"{du}","Je mange {du} pain."],[["some (feminine)","sebagian (feminin)"],"{de la}","Tu veux {de la} soupe ?"],[["some (before vowel)","sebagian (sebelum vokal)"],"{de l'}","Il boit {de l'}eau."],[["some (plural)","beberapa (jamak)"],"{des}","J'achète {des} pommes."],[["general (like, prefer)","umum (suka, lebih suka)"],"{le / la / les}","J'aime {le} pain. Je déteste {les} oignons."],[["quantity / negative","jumlah / negatif"],"{de}","beaucoup {de} pain, un kilo {de} pommes, pas {de} sucre"]]}],"examples":[["Le matin, je bois du café.",["In the morning I drink coffee.","Pagi hari saya minum kopi."]],["J'adore le chocolat.",["I love chocolate.","Saya sangat suka cokelat."]],["Je voudrais un peu de lait.",["I'd like a little milk.","Saya mau sedikit susu."]]],"tip":["After expressions of quantity use only de: beaucoup de, un peu de, une bouteille de, assez de — never 'beaucoup du'.","Setelah ungkapan jumlah pakai de saja: beaucoup de, un peu de, une bouteille de, assez de — jangan 'beaucoup du'."]},{"id":"a1-contractions","title":["À and de with the article (au, du, aux)","À dan de dengan artikel (au, du, aux)"],"what":["The prepositions à (to, at) and de (from, of) merge with le and les: à + le = au, à + les = aux, de + le = du, de + les = des. With la and l' they don't change.","Kata depan à (ke, di) dan de (dari, milik) bergabung dengan le dan les: à + le = au, à + les = aux, de + le = du, de + les = des. Dengan la dan l' tidak berubah."],"pattern":[{"head":["","+ le","+ la","+ l'","+ les"],"rows":[["à","{au} cinéma","à la gare","à l'hôpital","{aux} États-Unis"],["de","{du} bureau","de la plage","de l'école","{des} enfants"]],"note":["Typical uses: aller au marché, jouer au foot, jouer du piano, parler du film, la voiture du voisin.","Pemakaian khas: aller au marché, jouer au foot, jouer du piano, parler du film, la voiture du voisin."]}],"examples":[["Je vais au supermarché.",["I'm going to the supermarket.","Saya pergi ke supermarket."]],["Elle rentre du travail à six heures.",["She comes home from work at six.","Dia pulang kerja pukul enam."]],["C'est le livre des enfants.",["It's the children's book.","Ini buku anak-anak."]]],"tip":["Never write 'à le' or 'de le': it's always au and du. But 'à la' and 'de la' stay as they are.","Jangan menulis 'à le' atau 'de le': selalu au dan du. Tetapi 'à la' dan 'de la' tetap seperti itu."]},{"id":"a1-numbers-time","title":["Numbers, prices & telling the time","Angka, harga & menyebut jam"],"what":["70–99 are built from 60 and 80: soixante-dix (60+10), quatre-vingts (4×20), quatre-vingt-dix (4×20+10). For the time use il est + number + heure(s); the 24-hour clock is common for timetables.","70–99 dibentuk dari 60 dan 80: soixante-dix (60+10), quatre-vingts (4×20), quatre-vingt-dix (4×20+10). Untuk jam pakai il est + angka + heure(s); sistem 24 jam umum untuk jadwal."],"pattern":[{"title":["Numbers","Angka"],"head":["","","",""],"rows":[["1 un","11 onze","21 vingt {et} un","70 {soixante-dix}"],["2 deux","12 douze","22 vingt-deux","71 soixante {et} onze"],["5 cinq","16 seize","30 trente","80 {quatre-vingts}"],["7 sept","17 dix-sept","50 cinquante","81 quatre-vingt-un"],["10 dix","20 vingt","60 soixante","90 {quatre-vingt-dix} · 100 cent"]],"note":["Belgium and Switzerland say septante (70) and nonante (90); Switzerland often huitante (80).","Belgia dan Swiss memakai septante (70) dan nonante (90); Swiss sering huitante (80)."]},{"title":["Telling the time","Menyebut jam"],"head":[["Time","Jam"],["French","Prancis"]],"rows":[["1:00","Il est une {heure}."],["3:00","Il est trois {heures}."],["3:15","Il est trois heures {et quart}."],["3:30","Il est trois heures {et demie}."],["3:45","Il est quatre heures {moins le quart}."],["12:00 / 0:00","Il est {midi} / {minuit}."],[["at 8:00","pukul 8:00"],"{à} huit heures"]]}],"examples":[["Quelle heure est-il ? — Il est deux heures et demie.",["What time is it? — It's half past two.","Jam berapa? — Pukul setengah tiga."]],["Le train part à 18 h 40.",["The train leaves at 18:40.","Keretanya berangkat pukul 18.40."]],["Ça fait quatre-vingt-dix euros.",["That's ninety euros.","Totalnya sembilan puluh euro."]]],"tip":["Always say heure(s): 'Il est trois heures', not 'Il est trois'. Quatre-vingts has an -s only when nothing follows: quatre-vingt-deux.","Selalu ucapkan heure(s): 'Il est trois heures', bukan 'Il est trois'. Quatre-vingts ber-s hanya jika tidak diikuti angka lain: quatre-vingt-deux."]},{"id":"a1-futur-proche","title":["Near future: aller + infinitive","Masa depan dekat: aller + infinitif"],"what":["Aller (in the present) + infinitive talks about plans and things that are about to happen, like 'going to' in English. It is the most common way to talk about the future in conversation. In the negative, ne … pas surrounds aller.","Aller (kala kini) + infinitif menyatakan rencana dan hal yang akan segera terjadi, seperti 'going to' dalam bahasa Inggris. Ini cara paling umum membicarakan masa depan dalam percakapan. Dalam bentuk negatif, ne … pas mengapit aller."],"pattern":[{"head":[["Person","Persona"],"aller",["infinitive","infinitif"],["Negative","Negatif"]],"rows":[["je","{vais}","manger","je {ne vais pas} manger"],["tu","{vas}","partir","tu {ne vas pas} partir"],["il / elle / on","{va}","pleuvoir","il {ne va pas} pleuvoir"],["nous","{allons}","voyager","nous {n'allons pas} voyager"],["vous","{allez}","voir","vous {n'allez pas} voir"],["ils / elles","{vont}","arriver","ils {ne vont pas} arriver"]],"note":["Time words: ce soir, demain, ce week-end, la semaine prochaine, l'année prochaine.","Kata waktu: ce soir, demain, ce week-end, la semaine prochaine, l'année prochaine."]}],"examples":[["Je vais étudier ce soir.",["I'm going to study tonight.","Saya akan belajar malam ini."]],["Il va pleuvoir.",["It's going to rain.","Akan turun hujan."]],["Qu'est-ce que vous allez faire samedi ?",["What are you going to do on Saturday?","Apa yang akan Anda lakukan hari Sabtu?"]]],"tip":["No preposition between aller and the infinitive: 'Je vais manger', not 'Je vais à manger'.","Tidak ada kata depan antara aller dan infinitif: 'Je vais manger', bukan 'Je vais à manger'."]}]},{"id":"A2","name":["Elementary","Dasar"],"goal":["Talk about the past, routines and plans; deal with everyday situations.","Membicarakan masa lalu, rutinitas dan rencana; mengatasi situasi sehari-hari."],"topics":[{"id":"a2-pc-avoir","title":["Passé composé with avoir","Passé composé dengan avoir"],"what":["The passé composé tells completed actions in the past: 'I ate', 'I have eaten'. Most verbs form it with avoir in the present + past participle. Regular participles: -er → -é, -ir → -i, -re → -u.","Passé composé menceritakan tindakan yang sudah selesai di masa lalu. Kebanyakan kata kerja membentuknya dengan avoir kala kini + partisip lampau. Partisip beraturan: -er → -é, -ir → -i, -re → -u."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"avoir",["participle","partisip"]],"rows":[["je / j'","{ai}","parl{é}"],["tu","{as}","fin{i}"],["il / elle / on","{a}","vend{u}"],["nous","{avons}","mang{é}"],["vous","{avez}","chois{i}"],["ils / elles","{ont}","attend{u}"]],"note":["Negative: ne … pas around avoir: Je n'ai pas mangé. Question: Tu as mangé ? / As-tu mangé ?","Negatif: ne … pas mengapit avoir: Je n'ai pas mangé. Pertanyaan: Tu as mangé ? / As-tu mangé ?"]},{"title":["Irregular participles","Partisip tidak beraturan"],"head":[["Infinitive","Infinitif"],["Participle","Partisip"],["Infinitive","Infinitif"],["Participle","Partisip"]],"rows":[["avoir","{eu}","être","{été}"],["faire","{fait}","prendre","{pris}"],["dire","{dit}","écrire","{écrit}"],["voir","{vu}","lire","{lu}"],["boire","{bu}","pouvoir / vouloir","{pu} / {voulu}"],["mettre","{mis}","ouvrir","{ouvert}"]]}],"examples":[["Hier, j'ai travaillé jusqu'à huit heures.",["Yesterday I worked until eight.","Kemarin saya bekerja sampai pukul delapan."]],["Tu as vu le film ?",["Did you see the film?","Kamu sudah menonton filmnya?"]],["Nous n'avons pas fini.",["We haven't finished.","Kami belum selesai."]]],"tip":["Short adverbs go between avoir and the participle: j'ai bien dormi, il a déjà mangé, tu as trop bu.","Kata keterangan pendek diletakkan di antara avoir dan partisip: j'ai bien dormi, il a déjà mangé, tu as trop bu."]},{"id":"a2-pc-etre","title":["Passé composé with être","Passé composé dengan être"],"what":["About 15 verbs of movement or change of state, plus all reflexive verbs, use être instead of avoir. With être, the participle agrees with the subject like an adjective: elle est allée, ils sont partis.","Sekitar 15 kata kerja gerakan atau perubahan keadaan, serta semua kata kerja refleksif, memakai être sebagai ganti avoir. Dengan être, partisip menyesuaikan subjeknya seperti kata sifat: elle est allée, ils sont partis."],"pattern":[{"title":["The être verbs","Kata kerja dengan être"],"head":[["Pair","Pasangan"],["Participles","Partisip"]],"rows":[["aller / venir","{allé} / {venu}"],["arriver / partir","{arrivé} / {parti}"],["entrer / sortir","{entré} / {sorti}"],["monter / descendre","{monté} / {descendu}"],["naître / mourir","{né} / {mort}"],["rester / tomber / retourner / rentrer","{resté} / {tombé} / {retourné} / {rentré}"],[["+ devenir, revenir; all reflexive verbs","+ devenir, revenir; semua kata kerja refleksif"],"{devenu} / {revenu} / {levé}"]]},{"title":["Agreement","Kesesuaian"],"head":[["Subject","Subjek"],"aller",["Ending","Akhiran"]],"rows":[["je (m.) / je (f.)","suis allé / suis allé{e}","— / -e"],["il / elle","est allé / est allé{e}","— / -e"],["nous (m.) / nous (f.)","sommes allé{s} / allé{es}","-s / -es"],["ils / elles","sont allé{s} / sont allé{es}","-s / -es"]],"note":["Vous for one person: vous êtes allé(e); for several: allé(e)s.","Vous untuk satu orang: vous êtes allé(e); untuk beberapa orang: allé(e)s."]}],"examples":[["Elle est arrivée hier soir.",["She arrived last night.","Dia (perempuan) tiba tadi malam."]],["Nous sommes restés à la maison.",["We stayed at home.","Kami tinggal di rumah."]],["Je suis né à Lille.",["I was born in Lille.","Saya lahir di Lille."]]],"tip":["Never 'j'ai allé': aller always takes être. With avoir the participle does not agree with the subject: elle a mangé.","Jangan 'j'ai allé': aller selalu memakai être. Dengan avoir, partisip tidak menyesuaikan subjek: elle a mangé."]},{"id":"a2-imparfait","title":["Imparfait: past habits and descriptions","Imparfait: kebiasaan dan deskripsi masa lalu"],"what":["The imparfait describes how things were and what used to happen: background, habits, age, weather, ongoing situations. Take the nous form of the present, drop -ons, and add -ais, -ais, -ait, -ions, -iez, -aient. Only être is irregular (ét-).","Imparfait menggambarkan keadaan masa lalu dan hal yang biasa terjadi: latar, kebiasaan, umur, cuaca, situasi yang sedang berlangsung. Ambil bentuk nous kala kini, buang -ons, lalu tambahkan -ais, -ais, -ait, -ions, -iez, -aient. Hanya être yang tidak beraturan (ét-)."],"pattern":[{"head":[["Person","Persona"],["parler (nous parlons)","parler (nous parlons)"],["finir (nous finissons)","finir (nous finissons)"],"être","avoir"],"rows":[["je / j'","parl{ais}","finiss{ais}","ét{ais}","av{ais}"],["tu","parl{ais}","finiss{ais}","ét{ais}","av{ais}"],["il / elle / on","parl{ait}","finiss{ait}","ét{ait}","av{ait}"],["nous","parl{ions}","finiss{ions}","ét{ions}","av{ions}"],["vous","parl{iez}","finiss{iez}","ét{iez}","av{iez}"],["ils / elles","parl{aient}","finiss{aient}","ét{aient}","av{aient}"]],"note":["Typical words: avant, quand j'étais petit, d'habitude, tous les jours, souvent, toujours. il y a → il y avait; il fait beau → il faisait beau.","Kata khas: avant, quand j'étais petit, d'habitude, tous les jours, souvent, toujours. il y a → il y avait; il fait beau → il faisait beau."]}],"examples":[["Quand j'étais petite, j'habitais à la campagne.",["When I was little, I lived in the countryside.","Waktu kecil, saya tinggal di desa."]],["Tous les étés, nous allions à la mer.",["Every summer we used to go to the seaside.","Setiap musim panas kami biasa pergi ke pantai."]],["Il faisait froid et il pleuvait.",["It was cold and it was raining.","Udaranya dingin dan hujan turun."]]],"tip":["-ais, -ait and -aient all sound the same (è), so the subject tells you who: je parlais, il parlait, ils parlaient.","-ais, -ait dan -aient berbunyi sama (è), jadi subjeknya yang menunjukkan pelaku: je parlais, il parlait, ils parlaient."]},{"id":"a2-pc-imp","title":["Passé composé or imparfait?","Passé composé atau imparfait?"],"what":["In a story, the passé composé moves the action forward (what happened next), and the imparfait paints the background (what was going on, what things were like). An action in progress (imparfait) is often interrupted by a new event (passé composé).","Dalam cerita, passé composé memajukan alur (apa yang terjadi berikutnya), sedangkan imparfait melukiskan latarnya (apa yang sedang terjadi, bagaimana keadaannya). Tindakan yang sedang berlangsung (imparfait) sering disela peristiwa baru (passé composé)."],"pattern":[{"head":[["Passé composé","Passé composé"],["Imparfait","Imparfait"]],"rows":[[["completed event: Hier, j'{ai mangé} une pizza.","peristiwa selesai: Hier, j'{ai mangé} une pizza."],["habit: Le vendredi, je {mangeais} une pizza.","kebiasaan: Le vendredi, je {mangeais} une pizza."]],[["sequence: Je {suis rentré}, j'{ai dîné}, je {suis sorti}.","urutan: Je {suis rentré}, j'{ai dîné}, je {suis sorti}."],["background: Il {faisait} beau, il y {avait} du monde.","latar: Il {faisait} beau, il y {avait} du monde."]],[["interrupting event: … quand le téléphone {a sonné}.","peristiwa penyela: … quand le téléphone {a sonné}."],["action in progress: Je {dormais} …","tindakan berlangsung: Je {dormais} …"]],[["fixed duration: J'{ai habité} trois ans à Nice.","durasi tertentu: J'{ai habité} trois ans à Nice."],["description, age: J'{avais} huit ans. Elle {était} blonde.","deskripsi, umur: J'{avais} huit ans. Elle {était} blonde."]]]}],"examples":[["Je lisais quand Thomas est arrivé.",["I was reading when Thomas arrived.","Saya sedang membaca ketika Thomas datang."]],["Quand j'étais enfant, j'avais un chien.",["When I was a child, I had a dog.","Waktu kecil, saya punya anjing."]],["Hier, je suis allé chez le médecin parce que j'avais mal à la tête.",["Yesterday I went to the doctor because I had a headache.","Kemarin saya ke dokter karena kepala saya sakit."]]],"tip":["Ask: 'Could I film it as one event with a start and end?' → passé composé. 'Is it the scenery or the situation?' → imparfait.","Tanyakan: 'Bisakah saya merekamnya sebagai satu peristiwa dengan awal dan akhir?' → passé composé. 'Apakah itu latar atau situasinya?' → imparfait."]},{"id":"a2-pronominal","title":["Reflexive (pronominal) verbs","Kata kerja refleksif (pronominal)"],"what":["Pronominal verbs have a pronoun that refers back to the subject: je me lève (I get up). Many daily-routine verbs are pronominal. In the passé composé they always take être: je me suis levé(e). In commands, the pronoun goes after the verb: lève-toi.","Kata kerja pronominal punya kata ganti yang merujuk kembali ke subjek: je me lève (saya bangun). Banyak kata kerja rutinitas harian bersifat pronominal. Dalam passé composé selalu memakai être: je me suis levé(e). Dalam perintah, kata ganti diletakkan setelah kata kerja: lève-toi."],"pattern":[{"head":[["Person","Persona"],["Present","Kini"],["Passé composé","Passé composé"]],"rows":[["je","je {me} lève","je {me suis} levé(e)"],["tu","tu {te} lèves","tu {t'es} levé(e)"],["il / elle / on","il {se} lève","elle {s'est} levée"],["nous","nous {nous} levons","nous {nous sommes} levé(e)s"],["vous","vous {vous} levez","vous {vous êtes} levé(e)(s)"],["ils / elles","ils {se} lèvent","ils {se sont} levés"]],"note":["Others: se réveiller, se laver, s'habiller, se coucher, se promener, s'appeler, se dépêcher, s'amuser. Negative: je ne me lève pas. Command: lève-toi / ne te lève pas.","Lainnya: se réveiller, se laver, s'habiller, se coucher, se promener, s'appeler, se dépêcher, s'amuser. Negatif: je ne me lève pas. Perintah: lève-toi / ne te lève pas."]}],"examples":[["Je me lève à sept heures.",["I get up at seven.","Saya bangun pukul tujuh."]],["Elle s'est couchée tard.",["She went to bed late.","Dia tidur larut malam."]],["Dépêche-toi !",["Hurry up!","Cepatlah!"]]],"tip":["With an infinitive, the pronoun matches the subject: Je vais me coucher, nous allons nous promener.","Dengan infinitif, kata ganti menyesuaikan subjek: Je vais me coucher, nous allons nous promener."]},{"id":"a2-cod","title":["Direct object pronouns (le, la, les)","Kata ganti objek langsung (le, la, les)"],"what":["Direct object pronouns replace a person or thing that receives the action directly. They go before the conjugated verb (or before the infinitive when there is one). In the passé composé they go before avoir, and the participle agrees with a preceding direct object.","Kata ganti objek langsung menggantikan orang atau benda yang langsung dikenai tindakan. Diletakkan sebelum kata kerja terkonjugasi (atau sebelum infinitif jika ada). Dalam passé composé diletakkan sebelum avoir, dan partisip menyesuaikan objek langsung yang mendahuluinya."],"pattern":[{"head":[["Person","Persona"],["Pronoun","Kata ganti"],["Example","Contoh"]],"rows":[[["me / you","saya / kamu"],"{me (m')} / {te (t')}","Tu {m'}aimes ? Je {te} vois."],[["him, it (m.)","dia, itu (m.)"],"{le (l')}","Le film ? Je {le} regarde."],[["her, it (f.)","dia, itu (f.)"],"{la (l')}","La voiture ? Je {la} prends."],[["us / you (pl., polite)","kami / kalian, Anda"],"{nous} / {vous}","Il {nous} invite."],[["them","mereka, itu (jm.)"],"{les}","Mes clés ? Je ne {les} trouve pas."]]},{"title":["Position","Posisi"],"head":[["Structure","Struktur"],["Example","Contoh"]],"rows":[[["present","kini"],"Je {la} connais. Je ne {la} connais pas."],[["verb + infinitive","kata kerja + infinitif"],"Je vais {la} voir."],[["passé composé (agreement)","passé composé (kesesuaian)"],"Je {l'}ai vu{e}. (la robe)"],[["affirmative command","perintah positif"],"Prends-{le} ! / Ne {le} prends pas."]]}],"examples":[["Tu connais Julie ? — Oui, je la connais.",["Do you know Julie? — Yes, I know her.","Kamu kenal Julie? — Ya, saya kenal dia."]],["Ces chaussures, je les ai achetées hier.",["Those shoes, I bought them yesterday.","Sepatu itu saya beli kemarin."]],["Je vais t'appeler demain.",["I'm going to call you tomorrow.","Saya akan meneleponmu besok."]]],"tip":["Some verbs take a direct object in French but not in English: écouter (listen to), regarder (look at), chercher (look for), attendre (wait for): Je l'attends.","Beberapa kata kerja memakai objek langsung dalam bahasa Prancis: écouter, regarder, chercher, attendre: Je l'attends (saya menunggunya)."]},{"id":"a2-coi","title":["Indirect object pronouns (lui, leur)","Kata ganti objek tak langsung (lui, leur)"],"what":["Indirect object pronouns replace à + person: to whom something is given, said or written. In the 3rd person they are lui (to him/her) and leur (to them), for both genders. They go in the same position as direct pronouns, but the participle never agrees with them.","Kata ganti objek tak langsung menggantikan à + orang: kepada siapa sesuatu diberikan, dikatakan atau ditulis. Untuk persona ketiga bentuknya lui (kepadanya) dan leur (kepada mereka), untuk kedua gender. Letaknya sama dengan kata ganti langsung, tetapi partisip tidak pernah menyesuaikannya."],"pattern":[{"head":[["Person","Persona"],["Pronoun","Kata ganti"],["Example","Contoh"]],"rows":[[["to me / to you","kepada saya / kamu"],"{me (m')} / {te (t')}","Tu {me} donnes ton numéro ?"],[["to him / to her","kepadanya"],"{lui}","Je {lui} parle. (à Paul / à Léa)"],[["to us / to you","kepada kami / kalian"],"{nous} / {vous}","Il {nous} écrit souvent."],[["to them","kepada mereka"],"{leur}","Je {leur} téléphone. (à mes parents)"]],"note":["Verbs with à + person: parler à, téléphoner à, donner à, dire à, écrire à, répondre à, demander à, envoyer à, offrir à, plaire à.","Kata kerja dengan à + orang: parler à, téléphoner à, donner à, dire à, écrire à, répondre à, demander à, envoyer à, offrir à, plaire à."]}],"examples":[["Tu as parlé à ta mère ? — Oui, je lui ai parlé.",["Did you talk to your mother? — Yes, I talked to her.","Kamu sudah bicara dengan ibumu? — Ya, sudah."]],["Je leur envoie une carte.",["I'm sending them a card.","Saya mengirimi mereka kartu."]],["Ce film me plaît.",["I like this film. (it pleases me)","Saya suka film ini."]]],"tip":["Leur as a pronoun never takes -s (je leur parle); leurs with -s is only the possessive (leurs enfants).","Leur sebagai kata ganti tidak pernah ber-s (je leur parle); leurs dengan -s hanya kata kepemilikan (leurs enfants)."]},{"id":"a2-y-en","title":["The pronouns y and en","Kata ganti y dan en"],"what":["Y replaces a place introduced by à, en, dans, chez, sur… ('there'), or à + thing. En replaces de + noun ('some, of it, from there') and a noun after a number or quantity. Both go before the verb, like other object pronouns.","Y menggantikan tempat yang diawali à, en, dans, chez, sur… ('di sana / ke sana'), atau à + benda. En menggantikan de + kata benda ('sebagian, darinya, dari sana') dan kata benda setelah angka atau jumlah. Keduanya diletakkan sebelum kata kerja, seperti kata ganti objek lainnya."],"pattern":[{"head":[["Pronoun","Kata ganti"],["Replaces","Menggantikan"],["Example","Contoh"]],"rows":[["{y}",["à / en / dans / chez + place","à / en / dans / chez + tempat"],"Tu vas à Paris ? — Oui, j'{y} vais."],["{y}",["à + thing","à + benda"],"Tu penses à ton examen ? — Oui, j'{y} pense."],["{en}",["du / de la / des + noun","du / de la / des + kata benda"],"Tu veux du café ? — Oui, j'{en} veux."],["{en}",["number / quantity + noun","angka / jumlah + kata benda"],"Tu as des frères ? — J'{en} ai deux."],["{en}",["de + place (from there)","de + tempat (dari sana)"],"Tu viens de la gare ? — Oui, j'{en} viens."]],"note":["Fixed expressions: il y a, on y va (let's go), je m'en vais (I'm leaving), il y en a (there are some).","Ungkapan tetap: il y a, on y va (ayo pergi), je m'en vais (saya pergi), il y en a (ada beberapa)."]}],"examples":[["Tu es déjà allé au Maroc ? — Non, je n'y suis jamais allé.",["Have you ever been to Morocco? — No, I've never been there.","Kamu pernah ke Maroko? — Belum, saya belum pernah ke sana."]],["Des pommes ? J'en ai acheté un kilo.",["Apples? I bought a kilo (of them).","Apel? Saya membeli satu kilo."]],["On y va ?",["Shall we go?","Ayo berangkat?"]]],"tip":["Keep the number when you use en: 'J'en ai deux', not 'J'en ai'. For people after de or à, use stressed pronouns instead: je pense à elle.","Pertahankan angkanya saat memakai en: 'J'en ai deux', bukan 'J'en ai'. Untuk orang setelah de atau à, pakai kata ganti penekanan: je pense à elle."]},{"id":"a2-comparison","title":["Comparatives & superlatives","Perbandingan & superlatif"],"what":["Compare with plus / moins / aussi + adjective + que. For quantities use plus de / moins de / autant de + noun. The superlative is le/la/les plus + adjective (+ de). Bon becomes meilleur and bien becomes mieux.","Bandingkan dengan plus / moins / aussi + kata sifat + que. Untuk jumlah pakai plus de / moins de / autant de + kata benda. Superlatif = le/la/les plus + kata sifat (+ de). Bon menjadi meilleur dan bien menjadi mieux."],"pattern":[{"title":["Patterns","Pola"],"head":[["Meaning","Arti"],["Pattern","Pola"],["Example","Contoh"]],"rows":[[["more … than","lebih … daripada"],"{plus} + adj + {que}","Paris est {plus} grand {que} Lyon."],[["less … than","kurang … daripada"],"{moins} + adj + {que}","C'est {moins} cher {que} l'autre."],[["as … as","se… / sama … dengan"],"{aussi} + adj + {que}","Il est {aussi} grand {que} son père."],[["more / as much + noun","lebih banyak / sebanyak + kata benda"],"{plus de} / {autant de} + noun + {que}","J'ai {autant de} livres {que} toi."],[["the most … (in)","paling … (di)"],"le/la/les {plus} + adj (+ {de})","C'est la ville la {plus} belle {de} France."]]},{"title":["Irregular","Tidak beraturan"],"head":[["Base","Dasar"],["Comparative","Komparatif"],["Superlative","Superlatif"]],"rows":[[["bon (adjective)","bon (kata sifat)"],"{meilleur(e)}","le/la {meilleur(e)}"],[["bien (adverb)","bien (kata keterangan)"],"{mieux}","le {mieux}"],[["mauvais","mauvais"],"{pire} / plus mauvais","le/la {pire}"]]}],"examples":[["Mon frère est plus âgé que moi.",["My brother is older than me.","Kakak laki-laki saya lebih tua dari saya."]],["C'est le meilleur restaurant du quartier.",["It's the best restaurant in the area.","Ini restoran terbaik di lingkungan ini."]],["Elle parle mieux anglais que moi.",["She speaks English better than me.","Dia berbicara bahasa Inggris lebih baik dari saya."]]],"tip":["Never 'plus bon': use meilleur (adjective, with nouns) or mieux (adverb, with verbs): un meilleur prix, il chante mieux.","Jangan 'plus bon': pakai meilleur (kata sifat, dengan kata benda) atau mieux (kata keterangan, dengan kata kerja): un meilleur prix, il chante mieux."]},{"id":"a2-futur","title":["Simple future (futur simple)","Kala depan sederhana (futur simple)"],"what":["The futur simple adds -ai, -as, -a, -ons, -ez, -ont to the infinitive (-re verbs drop the final e). It is used for predictions, promises and more formal plans; in conversation aller + infinitive is more common. Several common verbs have an irregular stem, but the endings never change.","Futur simple menambahkan -ai, -as, -a, -ons, -ez, -ont ke infinitif (kata kerja -re kehilangan e akhir). Dipakai untuk prediksi, janji dan rencana yang lebih resmi; dalam percakapan aller + infinitif lebih umum. Beberapa kata kerja umum punya akar tidak beraturan, tetapi akhirannya tidak pernah berubah."],"pattern":[{"title":["Endings","Akhiran"],"head":[["Person","Persona"],"parler","finir","prendre"],"rows":[["je","parler{ai}","finir{ai}","prendr{ai}"],["tu","parler{as}","finir{as}","prendr{as}"],["il / elle / on","parler{a}","finir{a}","prendr{a}"],["nous","parler{ons}","finir{ons}","prendr{ons}"],["vous","parler{ez}","finir{ez}","prendr{ez}"],["ils / elles","parler{ont}","finir{ont}","prendr{ont}"]]},{"title":["Irregular stems","Akar tidak beraturan"],"head":[["Infinitive","Infinitif"],["Stem","Akar"],["Infinitive","Infinitif"],["Stem","Akar"]],"rows":[["être","{ser}-","avoir","{aur}-"],["aller","{ir}-","faire","{fer}-"],["venir","{viendr}-","pouvoir","{pourr}-"],["vouloir","{voudr}-","voir","{verr}-"],["devoir","{devr}-","savoir","{saur}-"],["il faut","il {faudr}a","envoyer","{enverr}-"]]}],"examples":[["Demain, il pleuvra dans le nord.",["Tomorrow it will rain in the north.","Besok akan turun hujan di utara."]],["Je t'appellerai ce soir.",["I'll call you tonight.","Saya akan meneleponmu malam ini."]],["Quand je serai grand, je serai pilote.",["When I grow up, I'll be a pilot.","Kalau sudah besar, saya akan jadi pilot."]]],"tip":["After quand about the future, French uses the future, not the present: 'Quand j'aurai le temps, je viendrai'.","Setelah quand tentang masa depan, bahasa Prancis memakai futur, bukan kala kini: 'Quand j'aurai le temps, je viendrai'."]},{"id":"a2-imperative","title":["Imperative (commands)","Imperatif (perintah)"],"what":["The imperative has three forms: tu, nous (let's) and vous, without subject pronouns. For -er verbs (and aller) the tu form drops the -s: parle, va. Être, avoir and savoir are irregular. Object pronouns come after an affirmative command, joined with a hyphen.","Imperatif punya tiga bentuk: tu, nous (ayo) dan vous, tanpa kata ganti subjek. Untuk kata kerja -er (dan aller) bentuk tu kehilangan -s: parle, va. Être, avoir dan savoir tidak beraturan. Kata ganti objek diletakkan setelah perintah positif, disambung tanda hubung."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Verb","Kata kerja"],"tu","nous","vous"],"rows":[["parler","parl{e}","parl{ons}","parl{ez}"],["finir","fin{is}","fin{issons}","fin{issez}"],["aller","{va}","allons","allez"],["être","{sois}","{soyons}","{soyez}"],["avoir","{aie}","{ayons}","{ayez}"]]},{"title":["With pronouns","Dengan kata ganti"],"head":[["Affirmative","Positif"],["Negative","Negatif"]],"rows":[["Regarde-{moi} !","Ne {me} regarde pas !"],["Prends-{le} !","Ne {le} prends pas !"],["Lève-{toi} !","Ne {te} lève pas !"],["Vas-{y} !","N'{y} va pas !"]],"note":["The -s returns before y and en for sound: vas-y, manges-en.","Huruf -s kembali sebelum y dan en demi bunyi: vas-y, manges-en."]}],"examples":[["Ferme la porte, s'il te plaît.",["Close the door, please.","Tutup pintunya, tolong."]],["Allons au parc !",["Let's go to the park!","Ayo ke taman!"]],["Ne vous inquiétez pas.",["Don't worry.","Jangan khawatir."]]],"tip":["Tu form of -er verbs has no -s: 'Mange !', not 'Manges !' (but 'Finis !', 'Prends !' keep theirs).","Bentuk tu kata kerja -er tanpa -s: 'Mange !', bukan 'Manges !' (tetapi 'Finis !', 'Prends !' tetap ber-s)."]},{"id":"a2-negations","title":["Other negatives: jamais, plus, rien, personne","Negasi lain: jamais, plus, rien, personne"],"what":["Pas can be replaced by other words: jamais (never), plus (no longer, not any more), rien (nothing), personne (nobody), que (only — not really negative). Ne stays before the verb. Rien and personne can also be subjects: Personne ne vient.","Pas dapat diganti kata lain: jamais (tidak pernah), plus (tidak lagi), rien (tidak apa-apa), personne (tidak seorang pun), que (hanya — tidak sungguh negatif). Ne tetap sebelum kata kerja. Rien dan personne juga bisa menjadi subjek: Personne ne vient."],"pattern":[{"head":[["Negation","Negasi"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["ne … {jamais}",["never","tidak pernah"],"Je {ne} bois {jamais} de café."],["ne … {plus}",["no longer","tidak lagi"],"Il {n'}habite {plus} ici."],["ne … {rien}",["nothing","tidak apa-apa"],"Je {ne} vois {rien}."],["ne … {personne}",["nobody","tidak seorang pun"],"Je {ne} connais {personne}."],["ne … {que}",["only","hanya"],"Je {n'}ai {qu'}un frère."],[["subject","subjek"],["Nothing / Nobody …","Tidak ada apa / siapa pun …"],"{Rien n'}est simple. {Personne ne} répond."]],"note":["Passé composé: jamais, plus, rien go before the participle (je n'ai rien vu); personne goes after it (je n'ai vu personne).","Passé composé: jamais, plus, rien sebelum partisip (je n'ai rien vu); personne setelahnya (je n'ai vu personne)."]}],"examples":[["Je ne fume plus.",["I don't smoke any more.","Saya sudah tidak merokok."]],["Il n'y a personne.",["There's nobody here.","Tidak ada orang."]],["Elle ne mange que des légumes.",["She only eats vegetables.","Dia hanya makan sayuran."]]],"tip":["Never add pas to these: 'Je ne vois rien', not 'Je ne vois pas rien'.","Jangan tambahkan pas: 'Je ne vois rien', bukan 'Je ne vois pas rien'."]},{"id":"a2-time-expr","title":["Time expressions: depuis, il y a, pendant, dans","Ungkapan waktu: depuis, il y a, pendant, dans"],"what":["Depuis + present = something started in the past and is still going on (English 'have been … for/since'). Il y a + time = ago. Pendant = for a (finished) duration. Dans + time = in (from now).","Depuis + kala kini = sesuatu dimulai di masa lalu dan masih berlangsung (sejak / sudah … selama). Il y a + waktu = yang lalu. Pendant = selama (durasi yang selesai). Dans + waktu = dalam … lagi (dari sekarang)."],"pattern":[{"head":[["Word","Kata"],["Meaning","Arti"],["Tense","Kala"],["Example","Contoh"]],"rows":[["{depuis}",["for / since (still true)","sejak / sudah selama (masih berlangsung)"],["present","kini"],"J'habite ici {depuis} deux ans."],["{il y a}",["ago","yang lalu"],["past","lampau"],"Je suis arrivé {il y a} deux ans."],["{pendant}",["for (finished period)","selama (sudah selesai)"],["past / any","lampau / lainnya"],"J'ai habité à Rome {pendant} deux ans."],["{dans}",["in (future)","… lagi"],["future","masa depan"],"Je pars {dans} deux jours."],["{en}",["in (time taken)","dalam waktu"],["any","apa saja"],"J'ai fini {en} une heure."]]}],"examples":[["J'apprends le français depuis six mois.",["I've been learning French for six months.","Saya sudah belajar bahasa Prancis selama enam bulan."]],["Elle est partie il y a une heure.",["She left an hour ago.","Dia pergi satu jam yang lalu."]],["Le film commence dans dix minutes.",["The film starts in ten minutes.","Filmnya mulai sepuluh menit lagi."]]],"tip":["Use the present with depuis, not the passé composé: 'Je travaille ici depuis 2020' (I have worked here since 2020).","Pakai kala kini dengan depuis, bukan passé composé: 'Je travaille ici depuis 2020'."]},{"id":"a2-recent-past","title":["Venir de, être en train de, être sur le point de","Venir de, être en train de, être sur le point de"],"what":["Three phrases place an action in time: venir de + infinitive (have just done), être en train de + infinitive (be in the middle of doing), être sur le point de + infinitive (be about to do).","Tiga frasa menempatkan tindakan dalam waktu: venir de + infinitif (baru saja), être en train de + infinitif (sedang), être sur le point de + infinitif (hampir / akan segera)."],"pattern":[{"head":[["Phrase","Frasa"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{venir de} + inf.",["have just done","baru saja"],"Je {viens d'}arriver."],["{être en train de} + inf.",["be (busy) doing","sedang"],"Elle {est en train de} cuisiner."],["{être sur le point de} + inf.",["be about to","akan segera"],"Le train {est sur le point de} partir."],["{aller} + inf.",["be going to","akan"],"Il {va} pleuvoir."]],"note":["In the past: Je venais de sortir quand il a appelé. J'étais en train de dormir.","Dalam lampau: Je venais de sortir quand il a appelé. J'étais en train de dormir."]}],"examples":[["Nous venons de manger.",["We've just eaten.","Kami baru saja makan."]],["Je suis en train de travailler, je te rappelle.",["I'm in the middle of working, I'll call you back.","Saya sedang bekerja, nanti saya telepon balik."]],["Ils viennent de partir.",["They've just left.","Mereka baru saja berangkat."]]],"tip":["Venir de uses the present even though the meaning is past: 'Je viens de finir' = I've just finished.","Venir de memakai kala kini meskipun artinya lampau: 'Je viens de finir' = saya baru saja selesai."]},{"id":"a2-places","title":["Prepositions with places: à, en, au, aux, chez","Kata depan tempat: à, en, au, aux, chez"],"what":["'To' and 'in' a place use the same preposition. Cities take à. Feminine countries (most ending in -e) take en; masculine countries take au; plural countries take aux. Chez + person means 'at/to someone's home or shop'.","'Ke' dan 'di' suatu tempat memakai kata depan yang sama. Kota memakai à. Negara feminin (kebanyakan berakhiran -e) memakai en; negara maskulin memakai au; negara jamak memakai aux. Chez + orang berarti 'di/ke rumah atau toko seseorang'."],"pattern":[{"head":[["Place","Tempat"],["to / in","ke / di"],["from","dari"],["Example","Contoh"]],"rows":[[["city","kota"],"{à}","{de}","Je vais {à} Rome. Je viens {de} Rome."],[["feminine country","negara feminin"],"{en}","{de / d'}","Elle habite {en} France. Il vient {d'}Italie."],[["masculine country","negara maskulin"],"{au}","{du}","Je vais {au} Japon. Il revient {du} Canada."],[["plural country","negara jamak"],"{aux}","{des}","Ils vivent {aux} États-Unis."],[["person's home / shop","rumah / toko seseorang"],"{chez}","de chez","Je dîne {chez} Paul. Je vais {chez} le médecin."]],"note":["Masculine countries to learn: le Japon, le Canada, le Maroc, le Brésil, le Portugal, le Mexique (exception in -e).","Negara maskulin yang perlu dihafal: le Japon, le Canada, le Maroc, le Brésil, le Portugal, le Mexique (pengecualian berakhiran -e)."]}],"examples":[["Je suis né au Maroc et j'habite en Belgique.",["I was born in Morocco and I live in Belgium.","Saya lahir di Maroko dan tinggal di Belgia."]],["On va chez toi ou chez moi ?",["Shall we go to your place or mine?","Kita ke rumahmu atau rumahku?"]],["Elle travaille à Genève.",["She works in Geneva.","Dia bekerja di Jenewa."]]],"tip":["Countries starting with a vowel also take en: en Iran, en Irak, en Israël, even if masculine.","Negara yang diawali vokal juga memakai en: en Iran, en Irak, en Israël, meskipun maskulin."]},{"id":"a2-relative-qui-que","title":["Relative pronouns qui and que","Kata ganti relatif qui dan que"],"what":["Qui and que both mean 'who / which / that'. Qui is the subject of the relative clause (it is followed by a verb). Que is the object (it is followed by a subject + verb). Que becomes qu' before a vowel; qui never changes.","Qui dan que sama-sama berarti 'yang'. Qui adalah subjek anak kalimat relatif (diikuti kata kerja). Que adalah objek (diikuti subjek + kata kerja). Que menjadi qu' sebelum vokal; qui tidak pernah berubah."],"pattern":[{"head":[["Relative","Relatif"],["Role","Fungsi"],["Followed by","Diikuti"],["Example","Contoh"]],"rows":[["{qui}",["subject","subjek"],["verb","kata kerja"],"La femme {qui} parle est ma tante."],["{que / qu'}",["object","objek"],["subject + verb","subjek + kata kerja"],"Le livre {que} je lis est génial."],["{que} + passé composé",["object before avoir → agreement","objek sebelum avoir → kesesuaian"],["subject + verb","subjek + kata kerja"],"La robe {que} j'ai acheté{e}."],["{ce qui / ce que}",["what (= the thing that)","apa yang"],["verb / subject","kata kerja / subjek"],"Je ne sais pas {ce qu'}il veut."]]}],"examples":[["C'est l'ami qui habite à Lyon.",["He's the friend who lives in Lyon.","Itu teman yang tinggal di Lyon."]],["Le film que nous avons vu était drôle.",["The film (that) we saw was funny.","Film yang kami tonton lucu."]],["Prends ce que tu veux.",["Take what you want.","Ambil apa yang kamu mau."]]],"tip":["In English you can drop 'that' (the book I read); in French que is compulsory: le livre que j'ai lu.","Dalam bahasa Inggris 'that' boleh dihilangkan; dalam bahasa Prancis que wajib: le livre que j'ai lu."]}]},{"id":"B1","name":["Intermediate","Menengah"],"goal":["Express wishes, feelings, opinions and hypotheses; tell and report stories.","Menyatakan keinginan, perasaan, pendapat dan pengandaian; menceritakan dan melaporkan kisah."],"topics":[{"id":"b1-subj-forms","title":["Present subjunctive: forms","Subjonctif présent: bentuk"],"what":["The subjonctif is a verb mood used mainly after que in certain expressions. For most verbs, take the ils form of the present, drop -ent and add -e, -es, -e, -ions, -iez, -ent. Verbs with two stems in the present (boire, prendre, venir) keep the nous stem for nous and vous.","Subjonctif adalah modus kata kerja yang terutama dipakai setelah que dalam ungkapan tertentu. Untuk kebanyakan kata kerja, ambil bentuk ils kala kini, buang -ent, lalu tambahkan -e, -es, -e, -ions, -iez, -ent. Kata kerja dengan dua akar di kala kini (boire, prendre, venir) memakai akar nous untuk nous dan vous."],"pattern":[{"title":["Regular formation","Pembentukan beraturan"],"head":[["Person","Persona"],["parler (ils parlent)","parler (ils parlent)"],["finir (ils finissent)","finir (ils finissent)"],["prendre (ils prennent)","prendre (ils prennent)"]],"rows":[["que je","parl{e}","finiss{e}","prenn{e}"],["que tu","parl{es}","finiss{es}","prenn{es}"],["qu'il / elle","parl{e}","finiss{e}","prenn{e}"],["que nous","parl{ions}","finiss{ions}","pren{ions}"],["que vous","parl{iez}","finiss{iez}","pren{iez}"],["qu'ils / elles","parl{ent}","finiss{ent}","prenn{ent}"]]},{"title":["Irregular verbs","Kata kerja tidak beraturan"],"head":[["Infinitive","Infinitif"],"que je","que nous","qu'ils"],"rows":[["être","{sois}","{soyons}","{soient}"],["avoir","{aie}","{ayons}","{aient}"],["aller","{aille}","allions","{aillent}"],["faire","{fasse}","{fassions}","{fassent}"],["pouvoir","{puisse}","{puissions}","{puissent}"],["savoir","{sache}","{sachions}","{sachent}"],["vouloir","{veuille}","voulions","{veuillent}"]]}],"examples":[["Il faut que tu viennes.",["You have to come.","Kamu harus datang."]],["Je veux que vous soyez à l'heure.",["I want you to be on time.","Saya ingin Anda tepat waktu."]],["Bien qu'il fasse froid, on sort.",["Although it's cold, we're going out.","Meskipun dingin, kita keluar."]]],"tip":["For -er verbs only nous and vous sound different from the present: que je parle (= je parle), but que nous parlions.","Untuk kata kerja -er hanya nous dan vous yang bunyinya berbeda dari kala kini: que je parle (= je parle), tetapi que nous parlions."]},{"id":"b1-subj-necessity","title":["Subjunctive after il faut que and wishes","Subjonctif setelah il faut que dan keinginan"],"what":["The subjonctif follows expressions of necessity (il faut que, il est nécessaire que), will and wishes (vouloir que, souhaiter que, préférer que, demander que) and some conjunctions (pour que, avant que, bien que, à condition que). If both clauses have the same subject, use an infinitive instead.","Subjonctif dipakai setelah ungkapan keharusan (il faut que, il est nécessaire que), kehendak dan keinginan (vouloir que, souhaiter que, préférer que, demander que) dan beberapa konjungsi (pour que, avant que, bien que, à condition que). Jika kedua klausa bersubjek sama, pakai infinitif."],"pattern":[{"head":[["Same subject → infinitive","Subjek sama → infinitif"],["Different subject → que + subjonctif","Subjek beda → que + subjonctif"]],"rows":[["Je veux {partir}.","Je veux que tu {partes}."],["Il faut {partir}. (general)","Il faut que nous {partions}."],["Je travaille pour {réussir}.","Je travaille pour que mes enfants {réussissent}."],["Je mange avant de {partir}.","Je mange avant que tu {partes}."],["—","Bien qu'il {soit} riche, il est malheureux."]],"note":["Espérer que takes the indicative: J'espère que tu viendras. Après que also takes the indicative.","Espérer que diikuti indikatif: J'espère que tu viendras. Après que juga diikuti indikatif."]}],"examples":[["Il faut que je parte.",["I have to go.","Saya harus pergi."]],["Mes parents veulent que j'apprenne l'anglais.",["My parents want me to learn English.","Orang tua saya ingin saya belajar bahasa Inggris."]],["Parle plus fort pour qu'on t'entende.",["Speak louder so that people can hear you.","Bicaralah lebih keras supaya orang bisa mendengarmu."]]],"tip":["Never 'Je veux que je…': same subject → infinitive (Je veux partir).","Jangan 'Je veux que je…': subjek sama → infinitif (Je veux partir)."]},{"id":"b1-subj-feelings","title":["Subjunctive after feelings and doubt","Subjonctif setelah perasaan dan keraguan"],"what":["Emotions (être content que, avoir peur que, regretter que), doubt (douter que) and negative or questioned opinions (je ne pense pas que, je ne crois pas que) take the subjonctif. Positive opinions and certainty (je pense que, je crois que, je suis sûr que) take the indicative.","Emosi (être content que, avoir peur que, regretter que), keraguan (douter que) dan pendapat negatif atau dalam pertanyaan (je ne pense pas que, je ne crois pas que) diikuti subjonctif. Pendapat positif dan kepastian (je pense que, je crois que, je suis sûr que) diikuti indikatif."],"pattern":[{"head":[["Type","Jenis"],["+ subjonctif","+ subjonctif"],["+ indicative","+ indikatif"]],"rows":[[["opinion","pendapat"],"Je ne pense pas qu'il {ait} raison.","Je pense qu'il {a} raison."],[["certainty","kepastian"],"Je doute qu'elle {vienne}.","Je suis sûr qu'elle {viendra}."],[["emotion","emosi"],"Je suis content que tu {sois} là.","—"],[["fear / regret","takut / menyesal"],"J'ai peur qu'il {soit} trop tard. Je regrette que tu {partes}.","—"],[["evaluation","penilaian"],"C'est dommage que vous ne {puissiez} pas venir.","Il est évident que vous {pouvez}."]]}],"examples":[["Je suis ravie que vous soyez venus.",["I'm delighted that you came.","Saya senang sekali Anda semua datang."]],["Je ne crois pas que ce soit vrai.",["I don't think it's true.","Saya rasa itu tidak benar."]],["Il est possible qu'il pleuve.",["It may rain.","Mungkin akan hujan."]]],"tip":["The switch often comes from negation: je crois que c'est vrai / je ne crois pas que ce soit vrai.","Perubahannya sering karena negasi: je crois que c'est vrai / je ne crois pas que ce soit vrai."]},{"id":"b1-conditional","title":["Present conditional (je parlerais)","Kondisional kini (je parlerais)"],"what":["The conditionnel uses the future stem (parler-, ser-, aur-, ir-, fer-…) with the imparfait endings (-ais, -ais, -ait, -ions, -iez, -aient). It expresses what would happen, polite requests, wishes, advice and unconfirmed information (in the news).","Conditionnel memakai akar futur (parler-, ser-, aur-, ir-, fer-…) dengan akhiran imparfait (-ais, -ais, -ait, -ions, -iez, -aient). Bentuk ini menyatakan apa yang akan terjadi (seandainya), permintaan sopan, keinginan, saran dan informasi yang belum dipastikan (dalam berita)."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"parler","être","pouvoir"],"rows":[["je","parler{ais}","ser{ais}","pourr{ais}"],["tu","parler{ais}","ser{ais}","pourr{ais}"],["il / elle / on","parler{ait}","ser{ait}","pourr{ait}"],["nous","parler{ions}","ser{ions}","pourr{ions}"],["vous","parler{iez}","ser{iez}","pourr{iez}"],["ils / elles","parler{aient}","ser{aient}","pourr{aient}"]]},{"title":["Uses","Pemakaian"],"head":[["Use","Pemakaian"],["Example","Contoh"]],"rows":[[["politeness","kesopanan"],"Je {voudrais} un café. {Pourriez}-vous m'aider ?"],[["wish","keinginan"],"J'{aimerais} visiter le Japon."],[["advice","saran"],"Tu {devrais} te reposer. À ta place, je {partirais}."],[["hypothesis","pengandaian"],"Avec plus d'argent, on {voyagerait} plus."]]}],"examples":[["J'aimerais habiter au bord de la mer.",["I'd like to live by the sea.","Saya ingin tinggal di tepi laut."]],["Vous pourriez fermer la fenêtre ?",["Could you close the window?","Bisakah Anda menutup jendela?"]],["Tu devrais dormir plus.",["You should sleep more.","Kamu sebaiknya tidur lebih banyak."]]],"tip":["je parlerai (future, -ai) and je parlerais (conditional, -ais) sound almost the same; check the meaning: 'will' or 'would'?","je parlerai (futur, -ai) dan je parlerais (kondisional, -ais) bunyinya hampir sama; periksa artinya: 'akan' atau 'akan (seandainya)'?"]},{"id":"b1-si","title":["Si clauses: real and hypothetical","Kalimat si: nyata dan pengandaian"],"what":["For a real, possible condition: si + present, then present, future or imperative. For an unlikely or imaginary condition: si + imparfait, then conditional. The verb right after si is never in the future or the conditional.","Untuk syarat nyata yang mungkin: si + kala kini, lalu kala kini, futur atau imperatif. Untuk syarat yang kecil kemungkinannya atau khayalan: si + imparfait, lalu kondisional. Kata kerja tepat setelah si tidak pernah dalam futur atau kondisional."],"pattern":[{"head":[["Type","Jenis"],["si clause","anak kalimat si"],["main clause","induk kalimat"],["Example","Contoh"]],"rows":[[["real","nyata"],["si + present","si + kini"],["present / future / imperative","kini / futur / imperatif"],"Si tu {as} le temps, {viens} ! S'il {pleut}, on {restera} ici."],[["hypothetical","pengandaian"],["si + imparfait","si + imparfait"],["conditional","kondisional"],"Si j'{avais} de l'argent, j'{achèterais} une maison."]],"note":["si + il / ils → s'il, s'ils (but si elle). 'Si j'étais toi…' = If I were you…","si + il / ils → s'il, s'ils (tetapi si elle). 'Si j'étais toi…' = Kalau saya jadi kamu…"]}],"examples":[["Si tu travailles, tu réussiras.",["If you work, you'll succeed.","Kalau kamu bekerja keras, kamu akan berhasil."]],["Si j'étais toi, je ne le ferais pas.",["If I were you, I wouldn't do it.","Kalau saya jadi kamu, saya tidak akan melakukannya."]],["S'il faisait beau, on irait à la plage.",["If the weather were nice, we'd go to the beach.","Kalau cuacanya bagus, kita akan ke pantai."]]],"tip":["Never 'si je serais' or 'si j'aurai': the si clause takes the present or the imparfait.","Jangan 'si je serais' atau 'si j'aurai': anak kalimat si memakai kala kini atau imparfait."]},{"id":"b1-pqp","title":["Pluperfect (plus-que-parfait)","Pluperfek (plus-que-parfait)"],"what":["Avoir or être in the imparfait + past participle tells an action that happened before another past action: 'had done'. The same rules apply as in the passé composé (être verbs, agreement).","Avoir atau être dalam imparfait + partisip lampau menceritakan tindakan yang terjadi sebelum tindakan lampau lainnya: 'sudah (lebih dulu)'. Aturannya sama dengan passé composé (kata kerja être, kesesuaian)."],"pattern":[{"head":[["Person","Persona"],["with avoir","dengan avoir"],["with être","dengan être"]],"rows":[["je / j'","{avais} mangé","{étais} parti(e)"],["tu","{avais} mangé","{étais} parti(e)"],["il / elle","{avait} mangé","{était} parti / partie"],["nous","{avions} mangé","{étions} parti(e)s"],["vous","{aviez} mangé","{étiez} parti(e)(s)"],["ils / elles","{avaient} mangé","{étaient} partis / parties"]]},{"title":["Timeline","Garis waktu"],"head":[["First (earlier past)","Lebih dulu"],["Then (past)","Kemudian"]],"rows":[["Le train {était déjà parti}","quand je {suis arrivé}."],["Je n'{avais jamais vu} la mer","avant ce voyage."]]}],"examples":[["Quand nous sommes arrivés, le film avait déjà commencé.",["When we arrived, the film had already started.","Ketika kami tiba, filmnya sudah dimulai."]],["Elle m'a dit qu'elle avait perdu ses clés.",["She told me she had lost her keys.","Dia bilang kepada saya bahwa dia kehilangan kuncinya."]],["Je n'étais jamais allé en Asie.",["I had never been to Asia.","Saya belum pernah ke Asia sebelumnya."]]],"tip":["Use it only when the order matters. A sequence told in order just needs the passé composé: Je suis rentré, j'ai mangé, je me suis couché.","Pakai hanya jika urutan penting. Urutan peristiwa yang diceritakan berurutan cukup dengan passé composé."]},{"id":"b1-dont-ou","title":["Relative pronouns dont, où and lequel","Kata ganti relatif dont, où dan lequel"],"what":["Dont replaces de + noun (verbs like parler de, avoir besoin de, se souvenir de; and 'whose'). Où is used for place and time ('where', 'when'). After other prepositions, use qui for people and lequel / laquelle / lesquels / lesquelles for things.","Dont menggantikan de + kata benda (kata kerja seperti parler de, avoir besoin de, se souvenir de; dan 'yang … -nya'). Où dipakai untuk tempat dan waktu ('tempat', 'saat'). Setelah kata depan lain, pakai qui untuk orang dan lequel / laquelle / lesquels / lesquelles untuk benda."],"pattern":[{"head":[["Relative","Relatif"],["Use","Pemakaian"],["Example","Contoh"]],"rows":[["{dont}",["replaces de + noun","menggantikan de + kata benda"],"Le livre {dont} je parle. (parler de)"],["{dont}",["whose","yang … -nya"],"La fille {dont} le père est médecin."],["{où}",["place","tempat"],"La ville {où} je suis né."],["{où}",["time","waktu"],"Le jour {où} on s'est rencontrés."],["prep. + {qui}",["people","orang"],"L'ami avec {qui} je voyage."],["prep. + {lequel / laquelle}",["things","benda"],"La table sur {laquelle} j'écris."]],"note":["à + lequel → auquel, auxquels; de + lequel → duquel (rare when dont is possible).","à + lequel → auquel, auxquels; de + lequel → duquel (jarang jika dont bisa dipakai)."]}],"examples":[["C'est le film dont tout le monde parle.",["It's the film everyone is talking about.","Itu film yang dibicarakan semua orang."]],["Voici la maison où j'ai grandi.",["Here's the house where I grew up.","Inilah rumah tempat saya tumbuh besar."]],["C'est quelque chose dont j'ai besoin.",["It's something I need.","Itu sesuatu yang saya butuhkan."]]],"tip":["Use où, not quand, for 'the day when': le jour où, l'année où.","Pakai où, bukan quand, untuk 'hari ketika': le jour où, l'année où."]},{"id":"b1-pronoun-order","title":["Two pronouns together (je le lui donne)","Dua kata ganti bersamaan (je le lui donne)"],"what":["When two object pronouns appear together before the verb, they follow a fixed order: me/te/se/nous/vous, then le/la/les, then lui/leur, then y, then en. In affirmative commands, the direct pronoun comes first and me/te become moi/toi.","Jika dua kata ganti objek muncul bersama sebelum kata kerja, urutannya tetap: me/te/se/nous/vous, lalu le/la/les, lalu lui/leur, lalu y, lalu en. Dalam perintah positif, kata ganti langsung lebih dulu dan me/te menjadi moi/toi."],"pattern":[{"title":["Order before the verb","Urutan sebelum kata kerja"],"head":["1","2","3","4","5"],"rows":[["me, te, se, nous, vous","le, la, les","lui, leur","y","en"]]},{"title":["Examples","Contoh"],"head":[["Sentence","Kalimat"],["With pronouns","Dengan kata ganti"]],"rows":[["Il me donne le livre.","Il {me le} donne."],["Je donne la clé à Paul.","Je {la lui} donne."],["Je donne les photos à mes parents.","Je {les leur} donne."],["Il y a du pain.","Il {y en} a."],[["command: Donne-moi le livre.","perintah: Donne-moi le livre."],"Donne-{le-moi} ! / Ne {me le} donne pas !"]]}],"examples":[["Tu me prêtes ta voiture ? — Oui, je te la prête.",["Will you lend me your car? — Yes, I'll lend it to you.","Boleh pinjam mobilmu? — Ya, saya pinjamkan."]],["Tu as donné le cadeau à Léa ? — Oui, je le lui ai donné.",["Did you give the present to Léa? — Yes, I gave it to her.","Kamu sudah memberikan hadiah itu kepada Léa? — Ya, sudah."]],["Dis-le-moi !",["Tell me!","Katakan kepada saya!"]]],"tip":["Lui and leur come after le/la/les, but me/te/nous/vous come before them: je te le dis, but je le lui dis.","Lui dan leur diletakkan setelah le/la/les, tetapi me/te/nous/vous sebelumnya: je te le dis, tetapi je le lui dis."]},{"id":"b1-gerondif","title":["Gérondif (en + -ant)","Gérondif (en + -ant)"],"what":["En + present participle (-ant) describes an action done at the same time as the main verb, or how something is done. The subject is the same as the main verb. Form it from the nous stem of the present: nous parlons → en parlant.","En + partisip kini (-ant) menggambarkan tindakan yang dilakukan bersamaan dengan kata kerja utama, atau cara sesuatu dilakukan. Subjeknya sama dengan kata kerja utama. Dibentuk dari akar nous kala kini: nous parlons → en parlant."],"pattern":[{"head":[["Infinitive","Infinitif"],["nous form","bentuk nous"],["Gérondif","Gérondif"],["Use","Pemakaian"]],"rows":[["parler","parlons","en parl{ant}",["at the same time","bersamaan"]],["finir","finissons","en finiss{ant}",["at the same time","bersamaan"]],["faire","faisons","en fais{ant}",["how (manner)","cara"]],["lire","lisons","en lis{ant}",["how (manner)","cara"]],["être / avoir / savoir","—","en {étant} / en {ayant} / en {sachant}",["irregular","tidak beraturan"]]]}],"examples":[["Je chante en prenant ma douche.",["I sing while I'm showering.","Saya bernyanyi sambil mandi."]],["On apprend en pratiquant.",["You learn by practising.","Kita belajar dengan berlatih."]],["Il s'est blessé en tombant.",["He hurt himself when he fell.","Dia terluka saat jatuh."]]],"tip":["Both actions must have the same subject: 'En sortant, j'ai vu Paul' means I was going out, not Paul.","Kedua tindakan harus bersubjek sama: 'En sortant, j'ai vu Paul' berarti saya yang keluar, bukan Paul."]},{"id":"b1-reported","title":["Reported speech","Kalimat tidak langsung"],"what":["With a present reporting verb (il dit que) tenses stay the same. With a past one (il a dit que) they shift back: present → imparfait, passé composé → plus-que-parfait, futur → conditionnel. Yes/no questions use si; question words stay; qu'est-ce que becomes ce que. Commands use de + infinitive.","Dengan kata kerja pelapor kala kini (il dit que) kala tidak berubah. Dengan kata kerja lampau (il a dit que) kala mundur: kini → imparfait, passé composé → plus-que-parfait, futur → conditionnel. Pertanyaan ya/tidak memakai si; kata tanya tetap; qu'est-ce que menjadi ce que. Perintah memakai de + infinitif."],"pattern":[{"head":[["Direct","Langsung"],["Reported (il a dit…)","Tidak langsung (il a dit…)"]],"rows":[["« Je suis fatiguée. »","Elle a dit qu'elle {était} fatiguée."],["« J'ai fini. »","Il a dit qu'il {avait fini}."],["« Je viendrai demain. »","Il a dit qu'il {viendrait} le lendemain."],["« Tu as faim ? »","Il m'a demandé {si} j'avais faim."],["« Où habites-tu ? »","Il m'a demandé {où} j'habitais."],["« Qu'est-ce que tu veux ? »","Il m'a demandé {ce que} je voulais."],["« Appelle-moi ! »","Elle m'a dit {de} l'appeler."]],"note":["Time words: aujourd'hui → ce jour-là, demain → le lendemain, hier → la veille, ici → là.","Kata waktu: aujourd'hui → ce jour-là, demain → le lendemain, hier → la veille, ici → là."]}],"examples":[["Thomas dit qu'il arrive en retard.",["Thomas says he's arriving late.","Thomas bilang dia datang terlambat."]],["Elle m'a dit qu'elle ne pouvait pas venir.",["She told me she couldn't come.","Dia bilang kepada saya bahwa dia tidak bisa datang."]],["Je lui ai demandé s'il voulait un café.",["I asked him if he wanted a coffee.","Saya bertanya apakah dia mau kopi."]]],"tip":["si + il → s'il: 'Je me demande s'il viendra'. Reported questions have normal word order, no inversion and no question mark.","si + il → s'il: 'Je me demande s'il viendra'. Pertanyaan tidak langsung memakai susunan biasa, tanpa inversi dan tanpa tanda tanya."]},{"id":"b1-passive","title":["Passive voice","Kalimat pasif"],"what":["The passive is formed with être (in any tense) + past participle, which agrees with the subject. The doer is introduced by par (sometimes de with feelings or states). French often prefers on + active verb instead of the passive in everyday speech.","Kalimat pasif dibentuk dengan être (dalam kala apa pun) + partisip lampau, yang menyesuaikan subjeknya. Pelakunya diperkenalkan dengan par (kadang de untuk perasaan atau keadaan). Dalam percakapan, bahasa Prancis sering lebih memilih on + kata kerja aktif daripada pasif."],"pattern":[{"head":[["Tense","Kala"],["Active","Aktif"],["Passive","Pasif"]],"rows":[[["present","kini"],"Le chef prépare le repas.","Le repas {est préparé} par le chef."],[["passé composé","passé composé"],"Picasso a peint ce tableau.","Ce tableau {a été peint} par Picasso."],[["future","futur"],"On construira un pont.","Un pont {sera construit}."],[["agreement","kesesuaian"],"On a fermé la porte.","La porte {a été fermée}."],[["de (states, feelings)","de (keadaan, perasaan)"],"Tout le monde aime ce professeur.","Ce professeur {est aimé de} tout le monde."]]}],"examples":[["Le musée a été construit en 1900.",["The museum was built in 1900.","Museum itu dibangun pada tahun 1900."]],["Les résultats seront publiés demain.",["The results will be published tomorrow.","Hasilnya akan diumumkan besok."]],["Ici, on parle anglais.",["English is spoken here.","Di sini orang berbicara bahasa Inggris."]]],"tip":["The passé composé of the passive is a été + participle: 'La maison a été vendue' (not 'est été').","Passé composé bentuk pasif adalah a été + partisip: 'La maison a été vendue' (bukan 'est été')."]},{"id":"b1-futur-anterieur","title":["Future perfect (futur antérieur)","Futur antérieur"],"what":["Avoir or être in the futur simple + past participle: an action that will be finished before another future moment ('will have done'). It is common after quand, dès que, lorsque, une fois que.","Avoir atau être dalam futur simple + partisip lampau: tindakan yang akan sudah selesai sebelum momen lain di masa depan ('akan sudah'). Sering dipakai setelah quand, dès que, lorsque, une fois que."],"pattern":[{"head":[["Person","Persona"],["with avoir","dengan avoir"],["with être","dengan être"]],"rows":[["je / j'","{aurai} fini","{serai} parti(e)"],["tu","{auras} fini","{seras} parti(e)"],["il / elle","{aura} fini","{sera} parti(e)"],["nous","{aurons} fini","{serons} parti(e)s"],["vous","{aurez} fini","{serez} parti(e)(s)"],["ils / elles","{auront} fini","{seront} partis / parties"]],"note":["Dès que j'aurai fini, je t'appellerai. = As soon as I've finished, I'll call you.","Dès que j'aurai fini, je t'appellerai. = Begitu saya selesai, saya akan meneleponmu."]}],"examples":[["Quand tu arriveras, j'aurai préparé le dîner.",["When you arrive, I'll have made dinner.","Saat kamu tiba, saya sudah menyiapkan makan malam."]],["Dès qu'il sera rentré, on mangera.",["As soon as he's back, we'll eat.","Begitu dia pulang, kita makan."]],["Dans un an, j'aurai terminé mes études.",["In a year, I'll have finished my studies.","Setahun lagi saya sudah menyelesaikan kuliah."]]],"tip":["English uses the present perfect after 'when/as soon as' (when I've finished); French uses the futur antérieur (quand j'aurai fini).","Bahasa Inggris memakai present perfect setelah 'when/as soon as'; bahasa Prancis memakai futur antérieur (quand j'aurai fini)."]},{"id":"b1-possessive-pronouns","title":["Possessive pronouns (le mien, la tienne…)","Kata ganti kepemilikan (le mien, la tienne…)"],"what":["Possessive pronouns replace possessive + noun: ma voiture → la mienne. They agree in gender and number with the thing owned and always take the article. À + le / les contract: au mien, aux tiens.","Kata ganti kepemilikan menggantikan kata kepemilikan + kata benda: ma voiture → la mienne. Menyesuaikan gender dan jumlah benda yang dimiliki dan selalu memakai artikel. À + le / les menyatu: au mien, aux tiens."],"pattern":[{"head":[["Owner","Pemilik"],["masc. sg.","mask. tg."],["fem. sg.","fem. tg."],["masc. pl.","mask. jm."],["fem. pl.","fem. jm."]],"rows":[["je","{le mien}","{la mienne}","{les miens}","{les miennes}"],["tu","{le tien}","{la tienne}","{les tiens}","{les tiennes}"],["il / elle","{le sien}","{la sienne}","{les siens}","{les siennes}"],["nous","{le nôtre}","{la nôtre}","{les nôtres}","{les nôtres}"],["vous","{le vôtre}","{la vôtre}","{les vôtres}","{les vôtres}"],["ils / elles","{le leur}","{la leur}","{les leurs}","{les leurs}"]],"note":["Le nôtre / le vôtre have a circumflex (ô); the possessive adjectives notre / votre do not.","Le nôtre / le vôtre memakai sirkumfleks (ô); kata sifat kepemilikan notre / votre tidak."]}],"examples":[["Ce n'est pas ma clé, c'est la tienne.",["It's not my key, it's yours.","Ini bukan kunci saya, itu milikmu."]],["Mes parents sont en France ; les siens habitent à Rome.",["My parents are in France; his live in Rome.","Orang tua saya di Prancis; orang tuanya tinggal di Roma."]],["Votre maison est plus grande que la nôtre.",["Your house is bigger than ours.","Rumah Anda lebih besar daripada rumah kami."]]],"tip":["Choose by the thing owned: Thomas → sa voiture → la sienne (not 'le sien', because voiture is feminine).","Pilih menurut benda yang dimiliki: Thomas → sa voiture → la sienne (bukan 'le sien', karena voiture feminin)."]},{"id":"b1-demonstrative-pronouns","title":["Demonstrative pronouns (celui, celle…)","Kata ganti tunjuk (celui, celle…)"],"what":["Celui / celle / ceux / celles replace a noun already mentioned ('the one(s)'). They cannot stand alone: they are followed by -ci / -là, by de + noun, or by a relative clause (qui, que, dont, où). Ceci / cela (ça) are neutral.","Celui / celle / ceux / celles menggantikan kata benda yang sudah disebut ('yang …'). Tidak bisa berdiri sendiri: diikuti -ci / -là, de + kata benda, atau anak kalimat relatif (qui, que, dont, où). Ceci / cela (ça) netral."],"pattern":[{"head":["",["Singular","Tunggal"],["Plural","Jamak"],["Example","Contoh"]],"rows":[[["masculine","maskulin"],"{celui}","{ceux}","Ce livre ou {celui-là} ?"],[["feminine","feminin"],"{celle}","{celles}","Ma voiture et {celle de} Paul."],[["+ relative","+ relatif"],"{celui qui / que}","{ceux qui / que}","{Ceux qui} veulent partir peuvent partir."],[["neutral","netral"],"{ceci / cela (ça)}","—","{Cela} m'étonne. Je veux {ça}."]]}],"examples":[["Quelle robe préfères-tu ? — Celle-ci.",["Which dress do you prefer? — This one.","Gaun mana yang kamu suka? — Yang ini."]],["Ce n'est pas mon vélo, c'est celui de mon frère.",["It's not my bike, it's my brother's.","Ini bukan sepeda saya, ini milik saudara laki-laki saya."]],["Celle que j'ai vue hier était plus jolie.",["The one I saw yesterday was prettier.","Yang saya lihat kemarin lebih cantik."]]],"tip":["'My brother's' is celui de mon frère; French has no 's form.","'Milik saudara saya' adalah celui de mon frère; bahasa Prancis tidak punya bentuk 's."]},{"id":"b1-connectors","title":["Connectors: cause, result, contrast","Kata penghubung: sebab, akibat, kontras"],"what":["Connectors link ideas. Parce que answers 'why'; puisque gives a cause both speakers know; comme starts the sentence. Donc and alors give a result. Mais, pourtant and cependant contrast; bien que needs the subjonctif.","Kata penghubung menghubungkan gagasan. Parce que menjawab 'mengapa'; puisque memberi sebab yang diketahui kedua pembicara; comme di awal kalimat. Donc dan alors memberi akibat. Mais, pourtant dan cependant untuk kontras; bien que memerlukan subjonctif."],"pattern":[{"head":[["Meaning","Arti"],["Connector","Kata penghubung"],["Example","Contoh"]],"rows":[[["cause","sebab"],"{parce que}, {puisque}, {comme} (start), {car}","{Comme} il pleuvait, on est restés."],[["cause + noun","sebab + kata benda"],"{à cause de} (bad), {grâce à} (good)","{Grâce à} toi, j'ai réussi."],[["result","akibat"],"{donc}, {alors}, {c'est pourquoi}","J'étais fatigué, {donc} je suis rentré."],[["contrast","kontras"],"{mais}, {pourtant}, {cependant}","C'est cher ; {pourtant}, je l'achète."],[["concession","konsesi"],"{bien que} + subj., {même si} + ind.","{Bien qu'}il soit tard, je reste. {Même s'}il est tard…"],[["opposition","pertentangan"],"{alors que}, {tandis que}","Il aime la mer {alors que} je préfère la montagne."]]}],"examples":[["Puisque tu es là, aide-moi.",["Since you're here, help me.","Karena kamu di sini, bantu saya."]],["Le vol a été annulé à cause de la neige.",["The flight was cancelled because of the snow.","Penerbangannya dibatalkan karena salju."]],["Même s'il pleut, nous sortirons.",["Even if it rains, we'll go out.","Meskipun hujan, kami akan keluar."]]],"tip":["Même si takes the indicative (même s'il pleut), bien que takes the subjonctif (bien qu'il pleuve).","Même si diikuti indikatif (même s'il pleut), bien que diikuti subjonctif (bien qu'il pleuve)."]},{"id":"b1-pp-agreement","title":["Past participle agreement","Kesesuaian partisip lampau"],"what":["Three rules: with être the participle agrees with the subject; with avoir it never agrees with the subject, but it agrees with a direct object placed before the verb (a pronoun la/les, que, or quelle…); with pronominal verbs it usually agrees with the subject, except when the verb has a direct object after it.","Tiga aturan: dengan être partisip menyesuaikan subjek; dengan avoir tidak pernah menyesuaikan subjek, tetapi menyesuaikan objek langsung yang diletakkan sebelum kata kerja (kata ganti la/les, que, atau quelle…); dengan kata kerja pronominal biasanya menyesuaikan subjek, kecuali jika ada objek langsung setelahnya."],"pattern":[{"head":[["Case","Kasus"],["Agreement","Kesesuaian"],["Example","Contoh"]],"rows":[[["être","être"],["with subject","dengan subjek"],"Elles sont parti{es}."],[["avoir, object after","avoir, objek setelahnya"],["none","tidak ada"],"Elle a mangé la pomme."],[["avoir, object before","avoir, objek sebelumnya"],["with the object","dengan objek"],"La pomme ? Elle l'a mangé{e}. Les fleurs que j'ai acheté{es}."],[["pronominal","pronominal"],["with subject","dengan subjek"],"Elle s'est levé{e}."],[["pronominal + direct object after","pronominal + objek langsung setelahnya"],["none","tidak ada"],"Elle s'est lavé les mains."]]}],"examples":[["Les lettres que tu as écrites sont belles.",["The letters you wrote are beautiful.","Surat-surat yang kamu tulis indah."]],["Ma sœur ? Je l'ai vue hier.",["My sister? I saw her yesterday.","Saudara perempuan saya? Saya melihatnya kemarin."]],["Ils se sont rencontrés à Paris.",["They met in Paris.","Mereka bertemu di Paris."]]],"tip":["Most agreements are silent in speech, but some show in sound: écrit / écrite, fait / faite, mis / mise, pris / prise.","Kebanyakan kesesuaian tidak terdengar, tetapi beberapa terdengar: écrit / écrite, fait / faite, mis / mise, pris / prise."]}]}]};
